    ["Choose one of the listed conversation providers."] = "Wähle einen der aufgelisteten Gesprächsanbieter aus.",
    ["Convai free tier"] = "Convai (kostenloser Tarif)",
    ["Convai: Mistral has no key yet"] = "Convai: Für Mistral gibt es noch keinen Schlüssel",
    ["Conversation provider"] = "Gesprächsanbieter",
    ["Deletes the saved key. Conversations go back to Convai free tier."] = "Löscht den gespeicherten Schlüssel. Gespräche kehren zu Convai (kostenloser Tarif) zurück.",
    ["Mistral did not accept that key."] = "Mistral hat diesen Schlüssel nicht akzeptiert.",
    ["Mistral replies are spoken by a local voice instead of the Convai cloud voice."] = "Mistral-Antworten werden von einer lokalen Stimme gesprochen statt der Convai-Cloud-Stimme.",
    ["Mistral: key not accepted"] = "Mistral: Schlüssel nicht akzeptiert",
    ["Mistral: model unavailable"] = "Mistral: Modell nicht verfügbar",
    ["The Mistral model is unavailable right now. Try again in a minute."] = "Das Mistral-Modell ist gerade nicht verfügbar. Versuche es in einer Minute erneut.",
    ["Waiting for the conversation to end"] = "Warten, bis das Gespräch endet",
    ["Convai: Local AI is not ready"] = "Convai: Local AI ist nicht bereit",
    ["Local AI"] = "Local AI",
    ["Local AI could not answer that. Try again in a moment."] = "Local AI konnte darauf nicht antworten. Versuche es gleich noch einmal.",
    ["Your model only thought and didn't answer. Turn thinking off for it in your model server, or pick a non-thinking model."] = "Dein Modell hat nur gedacht und nicht geantwortet. Schalte dafür das Denken in deinem Modell-Server aus oder wähle ein Non-Reasoning-Modell.",
    ["Your model server's context is too small for this character. Raise the context length in your server (8192 or more)."] = "Der Kontext deines Modell-Servers ist für diesen Charakter zu klein. Erhöhe die Kontextlänge auf deinem Server (8192 oder mehr).",
    ["Not enough free graphics memory to start Local AI. Try a smaller model in Settings."] = "Zu wenig freier Grafikspeicher für Local AI. Wähle in den Einstellungen ein kleineres Modell.",
    ["Local AI is still loading its model. Try again in a moment."] = "Local AI lädt noch sein Modell. Versuche es gleich noch einmal.",
    ["Local AI did not answer within {seconds} s. Try again, or choose a smaller model in Settings."] = "Local AI hat in {seconds} s nicht geantwortet. Versuche es erneut oder wähle ein kleineres Modell.",
    ["Local AI is not ready, so Convai took that message and did not answer in time."] = "Local AI ist nicht bereit, daher nahm Convai die Nachricht an, antwortete aber nicht rechtzeitig.",
    ["No reply arrived within {seconds} s. Try again."] = "Keine Antwort innerhalb von {seconds} s. Versuche es erneut.",
    ["The conversation service did not get that message. Try again."] = "Der Gesprächsdienst hat die Nachricht nicht erhalten. Versuche es erneut.",
    ["Not enough memory"] = "Zu wenig Grafikspeicher",
    ["Warming up"] = "Wird vorbereitet",
    ["Mistral cloud voice (Voxtral)"] = "Mistral-Cloudstimme (Voxtral)",
    ["{voice} · needs Mistral key"] = "{voice} · benötigt Mistral-API-Schlüssel",
    ["Loading the OmniVoice voice…"] = "Die OmniVoice-Stimme wird geladen…",
    ["OmniVoice voice is ready."] = "Die OmniVoice-Stimme ist bereit.",
    ["OmniVoice could not load. See Help in Settings."] = "OmniVoice konnte nicht geladen werden. Siehe Hilfe in den Einstellungen.",
    ["Loading the Pocket voice…"] = "Die Pocket-Stimme wird geladen…",
    ["Pocket voice is ready."] = "Die Pocket-Stimme ist bereit.",
    ["Pocket voice"] = "Pocket-Stimme",
    ["The Pocket voice (V’s voice, and a companion’s when you chose Pocket) could not start, so it stays silent. Pocket is part of the Runtime: nothing else needs installing. Restart the game. If it happens again, generate a report below and send it."] = "Die Pocket-Stimme (Vs Stimme und die eines Begleiters, wenn du Pocket gewählt hast) konnte nicht starten und bleibt deshalb stumm. Pocket gehört zur Runtime: Du musst nichts anderes installieren. Starte das Spiel neu. Wenn es wieder passiert, erzeuge unten einen Bericht und schicke ihn ab.",
    ["Windows (Smart App Control or an Application Control policy) blocks the files of the voice, so Pocket cannot run on this PC. Choose a cloud voice (Voxtral) in Settings."] = "Windows (Smart App Control oder eine Application-Control-Richtlinie) blockiert die Dateien der Stimme, deshalb kann Pocket auf diesem PC nicht laufen. Wähle in den Einstellungen eine Cloud-Stimme (Voxtral).",
    ["Windows (Smart App Control or an Application Control policy) blocks the files of the model server, so Local AI cannot run on this PC. Choose a cloud conversation provider in Settings."] = "Windows (Smart App Control oder eine Application-Control-Richtlinie) blockiert die Dateien des Modellservers, deshalb kann Local AI auf diesem PC nicht laufen. Wähle in den Einstellungen einen Cloud-Anbieter für Konversationen.",
    ["Pocket could not load. See Help in Settings."] = "Pocket konnte nicht geladen werden. Siehe Hilfe in den Einstellungen.",
    ["Local AI is warming up…"] = "Local AI wird vorbereitet…",
