    ["Everything together is too long. Shorten something so it stays under {max} characters."] = "Insgesamt ist das zu lang. Kürze etwas, damit es unter {max} Zeichen bleibt.",
    ["Example lines"] = "Beispielzeilen",
    ["Facts the character noticed while you talked. Change or delete the ones that are wrong."] = "Fakten, die der Charakter während deiner Gespräche bemerkt hat. Ändere oder lösche die falschen.",
    ["For example: V has a sister called Lena."] = "Zum Beispiel: V hat eine Schwester namens Lena.",
    ["Go back to the shipped text for {name}? All your changes to this character are removed."] = "Für {name} zum Originaltext zurückkehren? Alle deine Änderungen an diesem Charakter werden entfernt.",
