    ["Saved."] = "Gespeichert.",
    ["Search characters"] = "Charaktere suchen",
    ["Short facts you write yourself, such as a name or a promise. The character knows them in every talk."] = "Kurze Fakten, die du selbst schreibst, etwa einen Namen oder ein Versprechen. Der Charakter kennt sie in jedem Gespräch.",
    ["Short rules this character always follows when talking, for example: Never swear. Answer in one sentence."] = "Kurze Regeln, an die sich dieser Charakter beim Sprechen immer hält, zum Beispiel: Nie fluchen. In einem Satz antworten.",
    ["Short summary of earlier talks"] = "Kurze Zusammenfassung früherer Gespräche",
    ["Speaking rules"] = "Sprechregeln",
    ["Speaking style"] = "Sprechstil",
    ["Story characters"] = "Story-Charaktere",
    ["That character was not found."] = "Dieser Charakter wurde nicht gefunden.",
    ["The Local AI pack finds these. It is not installed or not ready, so none are collected now."] = "Das Local-AI-Paket findet diese. Es ist nicht installiert oder nicht bereit, deshalb werden jetzt keine gesammelt.",
    ["The bio is too long. Keep it under {max} characters."] = "Die Biografie ist zu lang. Halte sie unter {max} Zeichen.",
    ["The bio is too short. Use at least {max} characters."] = "Die Biografie ist zu kurz. Verwende mindestens {max} Zeichen.",
    ["The conversation service is not running, so the editor cannot open. Restart the game."] = "Der Gesprächsdienst läuft nicht, deshalb kann der Editor nicht geöffnet werden. Starte das Spiel neu.",
    ["The editor could not be opened. Try again."] = "Der Editor konnte nicht geöffnet werden. Versuche es noch einmal.",
    ["The editor is closed. You can close this tab."] = "Der Editor ist geschlossen. Du kannst diesen Tab schließen.",
    ["World rules"] = "Weltregeln",
    ["Rules for the whole world, used for every character in every talk: face to face, phone and group chats. Write facts and style, for example how people talk or what nobody knows. They never replace the mod’s own rules."] = "Regeln für die ganze Welt, gelten für jeden Charakter in jedem Gespräch: von Angesicht zu Angesicht, am Telefon und in Gruppenchats. Schreib Fakten und Stil auf, zum Beispiel wie Leute reden oder was niemand weiß. Sie ersetzen nie die eigenen Regeln des Mods.",
    ["For example: Nobody in Night City knows V’s name unless V tells them. Everyone speaks casually."] = "Zum Beispiel: Niemand in Night City kennt Vs Namen, solange V ihn nicht selbst verrät. Alle reden locker.",
    ["Applies to every provider: Local AI, Mistral and Custom in the character prompt, and Convai through its dynamic info."] = "Gilt für jeden Anbieter: Local AI, Mistral und Eigener im Charakter-Prompt, und Convai über seine dynamischen Infos.",
    ["The world rules are too long. Keep them under {max} characters."] = "Die Weltregeln sind zu lang. Halte sie unter {max} Zeichen.",
    ["Revert changes"] = "Änderungen verwerfen",
    ["Clear the world rules?"] = "Weltregeln leeren?",
    ["The example lines are too long together. Keep them under {max} characters in all."] = "Die Beispielzeilen sind zusammen zu lang. Halte sie insgesamt unter {max} Zeichen.",
    ["The speaking style is too long. Keep it under {max} characters."] = "Der Sprechstil ist zu lang. Halte ihn unter {max} Zeichen.",
    ["Things they always know"] = "Dinge, die sie immer wissen",
    ["Too many example lines. Keep {max} or fewer."] = "Zu viele Beispielzeilen. Behalte höchstens {max}.",
    ["Too many memories. Keep {max} or fewer."] = "Zu viele Erinnerungen. Behalte höchstens {max}.",
    ["Too many rules. Keep {max} or fewer."] = "Zu viele Regeln. Behalte höchstens {max}.",
    ["Who this character is, what they know and how they look. A long bio makes replies slower, so keep it tight."] = "Wer dieser Charakter ist, was er weiß und wie er aussieht. Eine lange Biografie macht Antworten langsamer, also halte sie knapp.",
    ["You have changes that are not saved. Leave without saving?"] = "Du hast ungespeicherte Änderungen. Ohne Speichern verlassen?",
    ["{count} of {max}"] = "{count} von {max}",
    ["Mature content"] = "Inhalte für Erwachsene",
    ["Local AI model"] = "Local-AI-Modell",
    ["Uncensored model"] = "Unzensiertes Modell",
    ["No model installed"] = "Kein Modell installiert",
    ["another model"] = "ein anderes Modell",
    ["The Local AI model you chose is missing, does not fit in the free graphics memory or did not start, so {model} was used instead."] = "Das gewählte Local-AI-Modell fehlt, passt nicht in den freien Grafikspeicher oder konnte nicht gestartet werden, daher wurde stattdessen {model} verwendet.",
    ["Local AI switched to {model}: the game is using most of your graphics memory."] = "Local AI wechselte zu {model}: Das Spiel nutzt den Großteil deines Grafikspeichers.",
    ["Choose one of the listed Local AI models."] = "Wähle eines der aufgelisteten Local-AI-Modelle.",
    ["Characters to invite"] = "Charaktere zum Einladen",
    ["Whose memories"] = "Wessen Erinnerungen",
    ["Invalid Mature content settings."] = "Ungültige Einstellungen für Inhalte für Erwachsene.",
    ["Your message was not sent. Open the text box again and retype it."] = "Deine Nachricht wurde nicht gesendet. Öffne das Textfeld erneut und gib sie noch einmal ein.",
    ["Not usable: {models}. See the Local AI notes, \"Add your own model\"."] = "Nicht verwendbar: {models}. Siehe die Hinweise zu Local AI, „Eigenes Modell hinzufügen“.",
    ["an embedding model, not a chat model"] = "ein Einbettungsmodell, kein Chatmodell",
    ["could not be read"] = "konnte nicht gelesen werden",
    ["file not found"] = "Datei nicht gefunden",
    ["not a valid GGUF file"] = "keine gültige GGUF-Datei",
    ["{name} (custom)"] = "{name} (eigenes)",
    ["{name}: {reason}"] = "{name}: {reason}",
    ["Preparing {name}: waiting for the conversation service to connect…"] = "{name} wird vorbereitet: Warten, bis der Gesprächsdienst verbunden ist…",
    ["Preparing {name}: waiting for the voice model to load…"] = "{name} wird vorbereitet: Warten, bis das Stimmmodell geladen ist…",
    ["Preparing {name}: waiting for the conversation connection to open…"] = "{name} wird vorbereitet: Warten, bis die Gesprächsverbindung geöffnet ist…",
    ["Preparing {name}: waiting for the game to place the character…"] = "{name} wird vorbereitet: Warten, bis das Spiel den Charakter platziert…",
    ["Preparing {name}: waiting for the memory service…"] = "{name} wird vorbereitet: Warten auf den Erinnerungsdienst…",
    ["Preparing {count} more companions…"] = "{count} weitere Begleiter werden vorbereitet…",
    ["The conversation service did not answer. Wait a moment, then invite again."] = "Der Gesprächsdienst hat nicht geantwortet. Warte einen Moment und lade dann erneut ein.",
    ["The voice model did not load. Check the voice in Settings or choose another one, then invite again."] = "Das Stimmmodell wurde nicht geladen. Prüfe die Stimme in den Einstellungen oder wähle eine andere und lade dann erneut ein.",
    ["The memory service did not respond. Check your connection, then invite again."] = "Der Erinnerungsdienst hat nicht reagiert. Prüfe deine Verbindung und lade dann erneut ein.",
    ["The conversation connection did not open. Check your connection, then invite again."] = "Die Gesprächsverbindung wurde nicht geöffnet. Prüfe deine Verbindung und lade dann erneut ein.",
    ["Convai sign-in is busy right now. Wait a few minutes, then invite again."] = "Die Anmeldung bei Convai ist gerade ausgelastet. Warte ein paar Minuten und lade dann erneut ein.",
    ["The Convai daily limit is used up. Choose another provider in Settings, or invite again tomorrow."] = "Das tägliche Limit von Convai ist aufgebraucht. Wähle in den Einstellungen einen anderen Anbieter oder lade morgen erneut ein.",
    ["The Convai daily limit is used up. It resets at {time}. Choose another provider in Settings, or invite again then."] = "Das tägliche Limit von Convai ist aufgebraucht. Reset um {time}. Wähle in den Einstellungen einen anderen Anbieter oder lade dann erneut ein.",
    ["Calls are not available during combat."] = "Anrufe sind während eines Kampfes nicht verfügbar.",
    ["Calls are not available right now."] = "Anrufe sind gerade nicht verfügbar.",
    ["Holocall ended: combat started."] = "Holocall beendet: Der Kampf hat begonnen.",
    ["Holocall with {name} ended."] = "Holocall mit {name} beendet.",
    ["Live picture unavailable. The call continues with the portrait."] = "Live-Bild nicht verfügbar. Der Anruf läuft mit dem Porträt weiter.",
    ["This contact cannot take a holocall."] = "Dieser Kontakt kann keinen Holocall annehmen.",
    ["You are already on a call."] = "Du bist bereits in einem Anruf.",
    ["A nearby companion makes one short comment as combat starts and another afterward.\n\nTen-minute cooldown after a fight. Conversations and story scenes come first. Loading a save resets the cooldown."] = "Ein Begleiter in der Nähe kommentiert kurz den Kampfbeginn und danach einmal.\n\nNach einem Kampf zehn Minuten Pause. Gespräche und Story-Szenen gehen vor. Laden eines Spielstands setzt die Pause zurück.",
    ["Ask a companion to drive to your selected map waypoint.\n\nGet into the passenger seat when they are ready."] = "Lass einen Begleiter zu deinem gewählten Kartenwegpunkt fahren.\n\nSteig auf dem Beifahrersitz ein, wenn er bereit ist.",
    ["Auto: follows the completed encounter in this save.\n\nCasual: speaks with that familiarity.\n\nOrdinary: keeps her usual manner.\n\nIt does not imply an ongoing relationship."] = "Automatisch: richtet sich nach der abgeschlossenen Begegnung in diesem Spielstand.\n\nZwanglos: spricht mit dieser Vertrautheit.\n\nGewöhnlich: bleibt bei ihrer üblichen Art.\n\nDas bedeutet keine fortbestehende Beziehung.",
    ["Auto: follows the relationship in this save.\n\nRomantic: speaks to V as a partner.\n\nOrdinary: keeps their usual manner.\n\nOnly changes how they talk, never your game choices."] = "Automatisch: richtet sich nach der Beziehung in diesem Spielstand.\n\nRomantisch: spricht mit V wie mit einem Partner.\n\nGewöhnlich: behält ihre übliche Art bei.\n\nVerändert nur die Art zu sprechen, nie deine Spielentscheidungen.",
    ["Bluetooth audio arrives a little late, so lips and subtitles can run ahead of the voice. This holds them back to match, for every voice.\n\nAuto: 150 ms while Windows plays through Bluetooth, none otherwise. Pick a value if your headset is faster or slower.\n\nThe game’s own dialogue has the same delay and does not correct it."] = "Bluetooth-Audio kommt etwas verzögert an, deshalb können Lippen und Untertitel der Stimme vorauslaufen. Dies hält sie passend zurück, bei jeder Stimme.\n\nAutomatisch: 150 ms, wenn Windows über Bluetooth abspielt, sonst keine. Wähle einen Wert, wenn dein Headset schneller oder langsamer ist.\n\nDer eigene Dialog des Spiels hat dieselbe Verzögerung und korrigiert sie nicht.",
    ["Chat history stays available across game launches.\n\nForgetting a character also clears their saved Chat messages and drafts. Forgetting all memories clears all saved chats."] = "Der Chatverlauf bleibt über Spielstarts erhalten.\n\nWenn du einen Charakter vergisst, werden auch seine gespeicherten Chatnachrichten und Entwürfe gelöscht. Wenn du alle Erinnerungen vergisst, werden alle gespeicherten Chats gelöscht.",
    ["Companions comment after you finish collecting loot from the world. Storage transfers stay silent.\n\nOrdinary comments are ten minutes apart; newly acquired Legendary gear has its own two-minute cooldown.\n\nPickups made during a fight are folded into one comment at its end."] = "Begleiter kommentieren, nachdem du Beute aus der Welt gesammelt hast. Lagertransfers bleiben stumm.\n\nGewöhnliche Kommentare liegen zehn Minuten auseinander; neu erhaltene legendäre Ausrüstung hat eine eigene Pause von zwei Minuten.\n\nWas du während eines Kampfes aufsammelst, wird am Ende zu einem einzigen Kommentar zusammengefasst.",
    ["Custom models are ones you added; they join the default choice by size."] = "Eigene Modelle sind die von dir hinzugefügten; sie reihen sich nach Größe ein.",
    ["Eyes only: the head stays still and just the eyes move.\n\nSubtle to Strong: the head turns toward you more and more."] = "Nur Augen: Der Kopf bleibt still, nur die Augen bewegen sich.\n\nDezent bis Stark: Der Kopf wendet sich dir immer stärker zu.",
    ["Forget all memories applies to these characters.\n\nBrowsing the catalogue or inviting a companion does not add anyone to this count."] = "Alle Erinnerungen vergessen gilt für diese Charaktere.\n\nDas Durchsuchen des Katalogs oder das Einladen eines Begleiters erhöht diese Anzahl nicht.",
    ["Gang members, NCPD officers, guards, ripperdocs, shopkeepers, bartenders and passers-by answer as their kind of person.\n\nThey do not know your story and forget you after a save load, except shopkeepers you come back to.\n\nNamed characters are not affected."] = "Gangmitglieder, NCPD-Beamte, Wachen, Ripperdocs, Ladenbesitzer, Barkeeper und Passanten antworten entsprechend ihrer Art.\n\nSie kennen deine Geschichte nicht und vergessen dich nach dem Laden eines Spielstands, außer Ladenbesitzern, zu denen du zurückkehrst.\n\nBenannte Charaktere sind nicht betroffen.",
    ["Talk to story characters"] = "Mit Story-Charakteren sprechen",
    ["{name} is busy right now."] = "{name} ist gerade beschäftigt.",
    ["{name} is not in your head right now."] = "{name} ist gerade nicht in deinem Kopf.",
    ["{name} is a story character. Turn on Talk to story characters in Esc > Mods."] = "{name}: Story-Charakter. Aktiviere „Mit Story-Charakteren sprechen“ (Esc > Mods).",
    ["Talk to ordinary NPCs is off. Turn it on in Esc > Mods."] = "„Mit gewöhnlichen NPCs sprechen“ ist aus. Aktiviere es in Esc > Mods.",
    ["{name} is a child and cannot be talked to."] = "{name} ist ein Kind und kann nicht angesprochen werden.",
    ["{name} is not a person and cannot be talked to."] = "{name} ist kein Mensch und kann nicht angesprochen werden.",
    ["{name} cannot be talked to: the mod cannot tell which voice fits."] = "{name} kann nicht angesprochen werden: Der Mod kennt die passende Stimme nicht.",
    ["If a character stops answering, voices stop or an error appears: choose Generate report and send the file it names to the developer, with a short note about what you were doing.\n\nThe logs listed below show what went wrong."] = "Wenn ein Charakter nicht mehr antwortet, Stimmen verstummen oder ein Fehler erscheint: Wähle Bericht erzeugen und schicke die darin genannte Datei mit einer kurzen Notiz, was du gerade getan hast, an den Entwickler.\n\nDie unten aufgeführten Protokolle zeigen, was schiefgelaufen ist.",
    ["Invited characters are prepared immediately. Their memories start when you actually talk to them.\n\nOne player identity is shared across all saves and stays the same after forgetting.\n\nCurrent game context describes the world you have loaded."] = "Eingeladene Charaktere werden sofort vorbereitet. Ihre Erinnerungen beginnen, sobald du tatsächlich mit ihnen sprichst.\n\nEine Spieleridentität wird über alle Spielstände geteilt und bleibt nach dem Vergessen gleich.\n\nDer aktuelle Spielkontext beschreibt die Welt, die du geladen hast.",
    ["Only Mature models found. Turn on Mature content to use them."] = "Nur Modelle für Erwachsene gefunden. Inhalte für Erwachsene aktivieren.",
    ["Something on this PC (a firewall or security software) is blocking the connection to the model server you added."] = "Etwas auf diesem PC (eine Firewall oder Sicherheitssoftware) blockiert die Verbindung zum Modellserver, den du hinzugefügt hast.",
    ["Never allowed: sex with minors or without consent, sex about real people, hate, real-world weapon or drug instructions. A safety check enforces the minors rule."] = "Verboten: Sex mit Minderjährigen oder ohne Zustimmung, mit echten Personen, Hass, Waffen- oder Drogenanleitungen. Sicherheitscheck erzwingt Minderjährigenregel.",
    ["Off: replies are text only and no voice is generated.\n\nWith Subtitles off as well, automatic reactions stay silent."] = "Aus: Antworten nur als Text, es wird keine Stimme erzeugt.\n\nWenn auch Untertitel aus sind, bleiben automatische Reaktionen stumm.",
    ["See what each character remembers and make one or all of them forget.\n\nMemories are kept across saves."] = "Sieh, woran sich jeder Charakter erinnert, und lass einen oder alle davon vergessen.\n\nErinnerungen bleiben über Spielstände erhalten.",
    ["Voxtral · not with Mature"] = "Voxtral · nicht mit 18+",
    ["Voxtral is not used with Mature content."] = "Voxtral wird bei Inhalten für Erwachsene nicht verwendet.",
    ["Needs Local AI or Custom."] = "Benötigt Local AI oder Eigener.",
    ["Mature content is turned off because you chose a model that is not a Mature model."] = "Inhalte für Erwachsene sind ausgeschaltet, weil du ein Modell gewählt hast, das kein Modell für Erwachsene ist.",
    ["Strong language, graphic violence, drugs and, between consenting adults, flirting and sex. Adults only (18+). Needs Local AI or Custom."] = "Starke Sprache, drastische Gewalt, Drogen, unter einvernehmlichen Erwachsenen Flirt und Sex. Nur 18+. Benötigt Local AI oder Eigener.",
    ["From Convai or Mistral, turning it on selects Local AI, or Custom when Local AI is not installed. With Local AI it also selects the largest uncensored model that fits. Turning it off restores your choices."] = "Von Convai oder Mistral aus wählt das Einschalten Local AI, oder Eigener, wenn Local AI nicht installiert ist. Mit Local AI wird außerdem das größte unzensierte Modell gewählt, das passt. Ausschalten stellt deine Auswahl wieder her.",
    ["Choosing Convai or Mistral turns it off. Voxtral is not used with it: a voice on Voxtral moves to Pocket and comes back when it is turned off."] = "Convai oder Mistral zu wählen schaltet dies aus. Voxtral wird damit nicht verwendet: Eine Stimme auf Voxtral wechselt zu Pocket und kehrt zurück, wenn dies ausgeschaltet wird.",
    ["Use it if companions seem to look above or below your eyes."] = "Nutze dies, wenn Begleiter scheinbar über oder unter deinen Augen schauen.",
    ["Voxtral · Mistral cloud"] = "Voxtral · Mistral-Cloud",
    ["Voxtral · needs Mistral key"] = "Voxtral · braucht Mistral-Key",
    ["{name} (custom · too large)"] = "{name} (eigenes · zu groß)",
    ["{name} (custom, {size} GB, needs {need} GB)"] = "{name} (eigenes, {size} GB, braucht {need} GB)",
    ["{name} (custom, {size} GB, too large for this card)"] = "{name} (eigenes, {size} GB, zu groß für diese Karte)",
    ["Clear memories about you for every character you have talked to.\n\nYour player identity stays. A confirmation comes first."] = "Erinnerungen an dich bei allen Charakteren löschen, mit denen du gesprochen hast.\n\nDeine Spieleridentität bleibt. Vorher folgt eine Bestätigung.",
    ["Saves a report file you can send to the developer.\n\nAPI keys, tokens, IDs, microphone audio and conversation text are left out. Without the conversation service, a shorter report is made from the files the game can read."] = "Speichert eine Berichtsdatei, die du an den Entwickler senden kannst.\n\nAPI-Schlüssel, Tokens, IDs, Mikrofonaudio und Gesprächstext sind nicht enthalten. Ohne den Gesprächsdienst wird ein kürzerer Bericht aus den Dateien erstellt, die das Spiel lesen kann.",
    ["The Mature pack’s uncensored models (for Local AI) give the full effect; standard models mostly refuse sex. Pack: installed."] = "Unzensierte Modelle des Mature pack (für Local AI) wirken voll; Standardmodelle lehnen Sex meist ab. Paket: installiert.",
    ["The Mature pack’s uncensored models (for Local AI) give the full effect; standard models mostly refuse sex. Pack: not installed (optional, on this mod’s Hugging Face page)."] = "Unzensierte Modelle des Mature pack (für Local AI) wirken voll; Standardmodelle lehnen Sex meist ab. Paket: nicht installiert (optional, Hugging-Face-Seite des Mods).",
    ["Until you choose one, Local AI loads the largest model that fits your free graphics memory.\n\nOne model at a time; a change applies when it next loads. A model that is missing, too large or failing is replaced by the largest that fits, with one notice."] = "Ohne Wahl lädt Local AI das größte Modell, das in den freien Grafikspeicher passt.\n\nEin Modell gleichzeitig; Änderung gilt beim nächsten Laden. Fehlt ein Modell, ist zu groß oder defekt, ersetzt das größte passende, mit einer Meldung.",
    ["Convai did not accept your API key. Check it in Settings > Conversation provider."] = "Convai hat deinen API-Schlüssel nicht akzeptiert. Prüfe ihn unter Einstellungen > Gesprächsanbieter.",
    ["Local AI could not start. Check Local AI in Settings > Conversation provider."] = "Local AI konnte nicht starten. Prüfe Local AI unter Einstellungen > Gesprächsanbieter.",
    ["Mistral did not accept your key. Check it in Settings > Conversation provider."] = "Mistral hat deinen Schlüssel nicht akzeptiert. Prüfe ihn unter Einstellungen > Gesprächsanbieter.",
    ["Mistral has no key yet, so Convai is used. Add your key in Settings > Conversation provider."] = "Für Mistral gibt es noch keinen Schlüssel, daher wird Convai verwendet. Füge deinen Schlüssel unter Einstellungen > Gesprächsanbieter hinzu.",
    ["Requires a Mistral key (add it in Settings > Conversation provider)"] = "Benötigt einen Mistral-API-Schlüssel (füge ihn unter Einstellungen > Gesprächsanbieter hinzu)",
    ["Speaking to companions needs Convai for now. Set Conversation provider to Convai free tier in Settings > Conversation provider, or type your message."] = "Mit Begleitern zu sprechen braucht vorerst Convai. Stelle unter Einstellungen > Gesprächsanbieter Convai (kostenloser Tarif) ein, oder tippe deine Nachricht.",
    ["Convai could not sign in. Try again in a moment, or choose Mistral or Local AI in Settings > Conversation provider."] = "Die Anmeldung bei Convai ist fehlgeschlagen. Versuche es gleich noch einmal, oder wähle unter Einstellungen > Gesprächsanbieter Mistral oder Local AI.",
    ["Your Convai API key has reached its plan limit. Try again later or add a different key in Settings > Conversation provider."] = "Dein Convai-API-Schlüssel hat sein Tarif-Limit erreicht. Versuche es später erneut oder füge unter Einstellungen > Gesprächsanbieter einen anderen Schlüssel hinzu.",
    ["Convai is answering right now, so these changes have no effect yet. Choose Mistral, Local AI or Custom as the conversation provider in the settings."] = "Convai antwortet gerade, deshalb haben diese Änderungen noch keine Wirkung. Wähle in den Einstellungen Mistral, Local AI oder Eigener als Gesprächsanbieter.",
    ["Your changes work with Mistral, Local AI and Custom. They do not apply to Convai."] = "Deine Änderungen funktionieren mit Mistral, Local AI und Eigener. Sie gelten nicht für Convai.",
    ["Paste"] = "Einfügen",
    ["no Omni pack"] = "ohne Omni-Paket",
    ["Add your Convai API key below to see and buy a plan."] = "Füge unten deinen Convai-API-Schlüssel hinzu, um Tarife zu sehen und einen zu kaufen.",
    ["Add your Convai API key first."] = "Füge zuerst deinen Convai-API-Schlüssel hinzu.",
    ["Add your Convai API key first: copy it, then choose Paste on the Convai API key row."] = "Füge zuerst deinen Convai-API-Schlüssel hinzu: Kopiere ihn, dann wähle in der Zeile Convai-API-Schlüssel die Option Einfügen.",
    ["Asking Convai for the payment page…"] = "Zahlungsseite wird von Convai abgefragt…",
    ["Asks Convai which plan your key has now. After paying, it can take about 15 seconds."] = "Fragt bei Convai ab, welchen Tarif dein Schlüssel jetzt hat. Nach der Zahlung kann es etwa 15 Sekunden dauern.",
    ["Billed every month."] = "Monatliche Abrechnung.",
    ["Billed once a year."] = "Jährliche Abrechnung.",
    ["Buy"] = "Kaufen",
    ["Check"] = "Prüfen",
    ["Check my plan"] = "Tarif prüfen",
    ["Checking your plan…"] = "Dein Tarif wird geprüft…",
    ["Choose Check my plan to ask Convai."] = "Wähle Tarif prüfen, um Convai zu fragen.",
    ["Contacting Convai…"] = "Verbindung zu Convai wird hergestellt…",
    ["Convai could not start the payment. Try again later."] = "Convai konnte die Zahlung nicht starten. Versuche es später erneut.",
    ["Convai did not accept your API key."] = "Convai hat deinen API-Schlüssel nicht akzeptiert.",
    ["Convai does not show a paid plan for your key yet."] = "Convai zeigt für deinen Schlüssel noch keinen Bezahltarif an.",
    ["Convai has not confirmed your plan yet. Check it in Settings > Convai paid tier."] = "Convai hat deinen Tarif noch nicht bestätigt. Prüfe ihn unter Einstellungen > Convai-Bezahltarif.",
    ["Convai paid tier"] = "Convai-Bezahltarif",
    ["Convai’s payment page is open in your browser. Your plan is active about 15 seconds after you pay."] = "Die Zahlungsseite von Convai ist in deinem Browser geöffnet. Dein Tarif ist etwa 15 Sekunden nach der Zahlung aktiv.",
    ["Convai’s payment service did not answer. Try again in a moment."] = "Der Zahlungsdienst von Convai hat nicht geantwortet. Versuche es gleich noch einmal.",
    ["Convai’s plans for this mod: more Convai conversations on your own Convai API key. Opens a page with the plans and their prices."] = "Convai-Tarife für diesen Mod: mehr Convai-Gespräche mit deinem eigenen Convai-API-Schlüssel. Öffnet eine Seite mit den Tarifen und ihren Preisen.",
    ["Conversations with Convai API key chosen as the provider use this plan."] = "Gespräche mit dem als Anbieter gewählten Convai-API-Schlüssel nutzen diesen Tarif.",
    ["Get your Convai API key"] = "Hol dir deinen Convai-API-Schlüssel",
    ["Manage or cancel plan"] = "Tarif verwalten oder kündigen",
    ["Free"] = "Gratis",
    ["Gamer, monthly"] = "Gamer, monatlich",
    ["Gamer, yearly"] = "Gamer, jährlich",
    ["Gamer Pro, monthly"] = "Gamer Pro, monatlich",
    ["Gamer Pro, yearly"] = "Gamer Pro, jährlich",
    ["Current plan"] = "Aktueller Tarif",
    ["This is your current plan. To change or cancel it, choose Manage or cancel plan below."] = "Das ist dein aktueller Tarif. Zum Ändern oder Kündigen wähle unten „Tarif verwalten oder kündigen“.",
    ["No key added"] = "Kein Schlüssel",
    ["Not checked yet"] = "Noch nicht geprüft",
    ["Opened in your browser."] = "In deinem Browser geöffnet.",
    ["Opening the page in your browser…"] = "Seite wird in deinem Browser geöffnet…",
    ["Opens Convai’s payment page (Stripe) in your browser. You pay Convai directly; the mod never sees your card. Your plan is active about 15 seconds after you pay, and conversations then use your Convai API key."] = "Öffnet die Zahlungsseite von Convai (Stripe) in deinem Browser. Du zahlst direkt bei Convai; der Mod sieht deine Karte nie. Dein Tarif ist etwa 15 Sekunden nach der Zahlung aktiv, und Gespräche nutzen dann deinen Convai-API-Schlüssel.",
    ["Opens convai.com in your browser. Sign in or make a free account, copy your API key, then come back and choose Paste below."] = "Öffnet convai.com in deinem Browser. Melde dich an oder erstelle ein kostenloses Konto, kopiere deinen API-Schlüssel und komm dann zurück und wähle unten Einfügen.",
    ["Opens your Convai billing page in your browser. Sign in with the same Convai account to change or cancel your plan."] = "Öffnet deine Abrechnungsseite bei Convai in deinem Browser. Melde dich mit demselben Convai-Konto an, um deinen Tarif zu ändern oder zu kündigen.",
    ["Plans"] = "Tarife",
    ["Plans Convai made for this mod. They give your own Convai API key more conversations; the free tier stays as it is."] = "Tarife, die Convai für diesen Mod anbietet. Sie geben deinem eigenen Convai-API-Schlüssel mehr Gespräche; der kostenlose Tarif bleibt wie er ist.",
    ["Prices in US dollars. You can cancel at any time on Convai’s billing page."] = "Preise in US-Dollar. Du kannst jederzeit auf der Abrechnungsseite von Convai kündigen.",
    ["The conversation service is not running, so plans cannot be shown. Restart the game."] = "Der Gesprächsdienst läuft nicht, daher können keine Tarife angezeigt werden. Starte das Spiel neu.",
    ["This key has no paid plan. Choose a plan below."] = "Dieser Schlüssel hat keinen Bezahltarif. Wähle unten einen Tarif.",
    ["Your Convai plan"] = "Dein Convai-Tarif",
    ["Your Convai plan is active."] = "Dein Convai-Tarif ist aktiv.",
    ["Your Convai plan is active. Choose Convai API key in Settings > Conversation provider."] = "Dein Convai-Tarif ist aktiv. Wähle unter Einstellungen > Gesprächsanbieter die Option Convai-API-Schlüssel.",
    ["Your Convai plan is active. Conversations now use your Convai API key."] = "Dein Convai-Tarif ist aktiv. Gespräche nutzen jetzt deinen Convai-API-Schlüssel.",
    ["Your browser could not be opened."] = "Dein Browser konnte nicht geöffnet werden.",
    ["Your plan could not be read right now. Try again in a moment."] = "Dein Tarif konnte gerade nicht gelesen werden. Versuche es gleich noch einmal.",
    ["{count} Convai interactions a month."] = "{count} Convai-Interaktionen pro Monat.",
    ["{plan}, {price} a month"] = "{plan}, {price} pro Monat",
    ["{plan}, {price} a year"] = "{plan}, {price} pro Jahr",
    ["Sign in with Convai"] = "Mit Convai anmelden",
    ["Sign in"] = "Anmelden",
    ["Opens Convai’s sign-in page in your browser.\n\nSign in or make a free account, and your Convai API key is saved on this computer, the same as Paste. You have five minutes."] = "Öffnet die Anmeldeseite von Convai in deinem Browser.\n\nMelde dich an oder erstelle ein kostenloses Konto. Dein Convai-API-Schlüssel wird dann auf diesem Computer gespeichert, genau wie bei Einfügen. Du hast fünf Minuten.",
    ["Opening Convai’s sign-in page in your browser…"] = "Anmeldeseite von Convai wird in deinem Browser geöffnet…",
    ["Sign in on the Convai page in your browser. Your key is saved here when you finish."] = "Melde dich auf der Convai-Seite in deinem Browser an. Dein Schlüssel wird hier gespeichert, wenn du fertig bist.",
    ["Signed in. Your Convai API key is saved."] = "Angemeldet. Dein Convai-API-Schlüssel ist gespeichert.",
    ["The sign-in took too long. Choose Sign in with Convai to try again."] = "Die Anmeldung hat zu lange gedauert. Wähle Mit Convai anmelden, um es noch einmal zu versuchen.",
    ["The sign-in did not finish. Try again, or copy your key from convai.com and choose Paste."] = "Die Anmeldung wurde nicht abgeschlossen. Versuche es erneut oder kopiere deinen Schlüssel von convai.com und wähle Einfügen.",
    ["Choose one of the listed voices for V."] = "Wähle eine der angebotenen Stimmen für V.",
    ["Pocket · On your PC"] = "Pocket · Auf deinem PC",
    ["Johnny in your head"] = "Johnny im Kopf",
    ["Johnny in your head is off. Turn it on in Settings > Conversations."] = "Johnny im Kopf ist ausgeschaltet. Schalte ihn in den Einstellungen > Gespräche ein.",
    ["Choose how often Johnny speaks up."] = "Wähle, wie oft Johnny sich zu Wort meldet.",
    ["A display name is too long. Keep each one under {max} characters."] = "Ein Anzeigename ist zu lang. Halte jeden unter {max} Zeichen.",
    ["A clip you add replaces the shipped voice of this character for Pocket, OmniVoice and the Voxtral cloud voice."] = "Ein Clip, den du hinzufügst, ersetzt die Originalstimme dieses Charakters für Pocket, OmniVoice und die Voxtral-Cloudstimme.",
    ["A new or removed clip counts from the next line this character speaks, once the current reply is over. Nothing needs restarting."] = "Ein neuer oder entfernter Clip gilt ab der nächsten Zeile dieses Charakters, sobald die aktuelle Antwort zu Ende ist. Es muss nichts neu gestartet werden.",
    ["A record name can only use letters, digits, dots, dashes and underscores, for example Character.Rebecca."] = "Ein Datensatzname darf nur Buchstaben, Ziffern, Punkte, Bindestriche und Unterstriche enthalten, zum Beispiel Character.Rebecca.",
    ["Add a display name"] = "Anzeigenamen hinzufügen",
    ["Add a record name"] = "Datensatznamen hinzufügen",
    ["Add a record name or a display name, so the game can find this character."] = "Füge einen Datensatznamen oder einen Anzeigenamen hinzu, damit das Spiel diesen Charakter finden kann.",
    ["Add voice clip"] = "Sprachclip hinzufügen",
    ["Another character of yours, {other}, already answers to this record or name."] = "Ein anderer deiner Charaktere, {other}, reagiert bereits auf diesen Datensatz oder Namen.",
    ["Choose a gender"] = "Wähle ein Geschlecht",
    ["Choose a gender."] = "Wähle ein Geschlecht.",
    ["Chosen file: {name} ({size}). It is checked when you save it."] = "Gewählte Datei: {name} ({size}). Sie wird geprüft, wenn du sie speicherst.",
    ["Chosen file: {name}, {seconds} seconds."] = "Gewählte Datei: {name}, {seconds} Sekunden.",
    ["Clip removed."] = "Clip entfernt.",
    ["Delete character"] = "Charakter löschen",
    ["Delete {name}? The character, its voice clip and what it remembers of you are removed."] = "{name} löschen? Der Charakter, sein Sprachclip und alles, woran er sich von dir erinnert, werden entfernt.",
    ["Display names"] = "Anzeigenamen",
    ["Female"] = "Weiblich",
    ["Filled in from the character you were facing: {name}."] = "Ausgefüllt mit dem Charakter, dem du gegenüberstehst: {name}.",
    ["For example: Character.Rebecca"] = "Zum Beispiel: Character.Rebecca",
    ["For example: Rebecca"] = "Zum Beispiel: Rebecca",
    ["Gender"] = "Geschlecht",
    ["Give the character a name."] = "Gib dem Charakter einen Namen.",
    ["How the game finds this character"] = "So findet das Spiel diesen Charakter",
    ["It picks the voice when the character has no clip."] = "Wenn der Charakter keinen Clip hat, wählt das Geschlecht die Stimme.",
    ["Male"] = "Männlich",
    ["Memories"] = "Erinnerungen",
    ["Name"] = "Name",
    ["New character"] = "Neuer Charakter",
    ["No clip yet."] = "Noch kein Clip.",
    ["Optional. Pocket, OmniVoice and the Voxtral cloud voice copy a clip you add. Without one the character speaks with a generic voice that fits the gender."] = "Optional. Pocket, OmniVoice und die Voxtral-Cloudstimme kopieren einen Clip, den du hinzufügst. Ohne Clip spricht der Charakter mit einer allgemeinen Stimme, die zum Geschlecht passt.",
    ["Play saved clip"] = "Gespeicherten Clip abspielen",
    ["Record names"] = "Datensatznamen",
    ["Remove clip"] = "Clip entfernen",
    ["Remove the voice clip? The character goes back to a generic voice."] = "Sprachclip entfernen? Der Charakter kehrt zu einer allgemeinen Stimme zurück.",
    ["Remove the voice clip? {name} goes back to the shipped voice."] = "Sprachclip entfernen? {name} kehrt zur Originalstimme zurück.",
    ["Save clip"] = "Clip speichern",
    ["Save the character first. Then it can have a voice clip, and it starts to remember your talks."] = "Speichere den Charakter zuerst. Danach kann er einen Sprachclip bekommen und sich an deine Gespräche erinnern.",
    ["Saved clip: {seconds} seconds."] = "Gespeicherter Clip: {seconds} Sekunden.",
    ["Saved. The clip is a little long: 10 to 18 seconds copies best."] = "Gespeichert. Der Clip ist etwas lang: 10 bis 18 Sekunden werden am besten kopiert.",
    ["Saved. The clip is a little short: 10 to 18 seconds copies best."] = "Gespeichert. Der Clip ist etwas kurz: 10 bis 18 Sekunden werden am besten kopiert.",
    ["That file is not a recording the voices can read. Use a WAV, MP3, OGG or FLAC file."] = "Diese Datei ist keine Aufnahme, die die Stimmen lesen können. Verwende eine WAV-, MP3-, OGG- oder FLAC-Datei.",
    ["That file is too big for a voice clip."] = "Diese Datei ist zu groß für einen Sprachclip.",
    ["The clip is mostly silence. Use a clip where somebody is talking most of the time."] = "Der Clip besteht größtenteils aus Stille. Verwende einen Clip, in dem die meiste Zeit jemand spricht.",
    ["The clip is too long. Use at most {max} seconds."] = "Der Clip ist zu lang. Verwende höchstens {max} Sekunden.",
    ["The clip is too short. Use at least {min} seconds."] = "Der Clip ist zu kurz. Verwende mindestens {min} Sekunden.",
    ["The game did not name anyone. Face the character, then choose Settings > Edit characters > Open in the game again."] = "Das Spiel hat niemanden benannt. Wende dich dem Charakter zu und wähle dann im Spiel erneut Einstellungen > Charaktere bearbeiten > Öffnen.",
    ["The game recognises the person you talk to by a record name, a display name, or both. A record name looks like Character.Rebecca or NCA.Rebecca. Add at least one."] = "Das Spiel erkennt die Person, mit der du sprichst, an einem Datensatznamen, einem Anzeigenamen oder an beidem. Ein Datensatzname sieht zum Beispiel so aus: Character.Rebecca oder NCA.Rebecca. Füge mindestens einen hinzu.",
    ["The name is too long. Keep it under {max} characters."] = "Der Name ist zu lang. Halte ihn unter {max} Zeichen.",
    ["The name of the character’s record in the game files."] = "Der Name des Datensatzes des Charakters in den Spieldateien.",
    ["The name the character goes by. They give it when somebody asks who they are."] = "Der Name, unter dem der Charakter bekannt ist. Den Namen nennt er, wenn jemand fragt, wer er ist.",
    ["The name the game shows for the character."] = "Der Name, den das Spiel für den Charakter anzeigt.",
    ["The recording is distorted. Record it again, a little quieter."] = "Die Aufnahme ist verzerrt. Nimm sie noch einmal auf, etwas leiser.",
    ["The recording is too low in quality. Use at least {min} Hz."] = "Die Aufnahmequalität ist zu niedrig. Verwende mindestens {min} Hz.",
    ["The recording is too quiet to copy. Record it louder, or closer to the microphone."] = "Die Aufnahme ist zu leise zum Kopieren. Nimm lauter auf oder näher am Mikrofon.",
    ["The saved clip could not be loaded."] = "Der gespeicherte Clip konnte nicht geladen werden.",
    ["The words said in the clip are too long. Keep them under {max} characters."] = "Der Text im Clip ist zu lang. Halte ihn unter {max} Zeichen.",
    ["This character speaks with a generic voice that fits the gender."] = "Dieser Charakter spricht mit einer allgemeinen Stimme, die zum Geschlecht passt.",
    ["This character speaks with the shipped voice."] = "Dieser Charakter spricht mit der Originalstimme.",
    ["This computer cannot convert that file. Save it as a WAV and try again."] = "Dieser Computer kann diese Datei nicht umwandeln. Speichere sie als WAV und versuche es erneut.",
    ["Too many display names. Keep {max} or fewer."] = "Zu viele Anzeigenamen. Behalte {max} oder weniger.",
    ["Too many record names. Keep {max} or fewer."] = "Zu viele Datensatznamen. Behalte {max} oder weniger.",
    ["Type the words said in the clip, at least {min} characters."] = "Tippe die Worte aus dem Clip ein, mindestens {min} Zeichen.",
    ["Type what the clip says, as spoken. OmniVoice needs it to copy the voice."] = "Tippe ein, was im Clip gesagt wird, so wie es gesprochen wird. OmniVoice braucht das, um die Stimme zu kopieren.",
    ["Use the character I’m facing"] = "Den Charakter vor mir verwenden",
    ["Use {min} to {max} seconds of one person speaking clearly, with no music or other voices. {goodMin} to {goodMax} seconds copies best. WAV, MP3, OGG or FLAC."] = "Verwende {min} bis {max} Sekunden von einer Person, die deutlich spricht, ohne Musik oder andere Stimmen. {goodMin} bis {goodMax} Sekunden werden am besten kopiert. WAV, MP3, OGG oder FLAC.",
    ["Voice"] = "Stimme",
    ["You have as many voice clips as the editor keeps ({max}). Remove one first."] = "Du hast so viele Sprachclips, wie der Editor speichert ({max}). Entferne zuerst einen.",
    ["Who this character is, what they know and how they look. Writing it as “I am …” works best. A long bio makes replies slower, so keep it tight."] = "Wer dieser Charakter ist, was er weiß und wie er aussieht. Am besten schreibst du es als „Ich bin …“. Eine lange Biografie macht Antworten langsamer, also halte sie knapp.",
    ["Words said in the clip"] = "Worte im Clip",
    ["You have made as many characters as the editor keeps ({max}). Delete one first."] = "Du hast so viele Charaktere erstellt, wie der Editor speichern kann ({max}). Lösche zuerst einen.",
    ["Your character"] = "Dein Charakter",
    ["Your characters"] = "Deine Charaktere",
    ["Your own characters talk only with Mistral, Local AI or Custom. With Convai they speak as an ordinary person."] = "Deine eigenen Charaktere sprechen nur mit Mistral, Local AI oder Eigener. Mit Convai sprechen sie wie ganz normale Personen.",
    ["{name} is one of your own characters. They need Mistral, Local AI or Custom, so with Convai they talk as an ordinary person."] = "{name} ist einer deiner eigenen Charaktere. Er braucht Mistral, Local AI oder Eigener, daher spricht er mit Convai wie eine ganz normale Person.",
    ["{other} already has a profile in the mod, and that profile always wins. Use another record or name."] = "{other} hat bereits ein Profil im Mod, und dieses Profil hat immer Vorrang. Verwende einen anderen Datensatz oder Namen.",
    ["A pack is one folder too deep. See Help in Settings."] = "Ein Paket liegt einen Ordner zu tief. Siehe Hilfe in den Einstellungen.",
    ["All files found."] = "Alle Dateien gefunden.",
    ["Browser"] = "Browser",
    ["Found."] = "Gefunden.",
    ["Found: {list}."] = "Gefunden: {list}.",
    ["Game version"] = "Spielversion",
    ["Graphics card"] = "Grafikkarte",
    ["Internet"] = "Internet",
    ["Loaded."] = "Geladen.",
    ["Local AI could not start. Generate a report below and send it, or choose another conversation provider."] = "Local AI konnte nicht starten. Erzeuge unten einen Bericht und schicke ihn ab, oder wähle einen anderen Gesprächsanbieter.",
    ["Local AI found no graphics card it can use. It needs an NVIDIA or AMD card with a current driver. Update the driver, or choose another conversation provider."] = "Local AI hat keine nutzbare Grafikkarte gefunden. Nötig ist eine NVIDIA- oder AMD-Karte mit aktuellem Treiber. Aktualisiere den Treiber oder wähle einen anderen Gesprächsanbieter.",
    ["Missing: {files}. Extract the Scripts zip into the Cyberpunk 2077 folder again and let it replace the files."] = "Fehlend: {files}. Entpacke das Scripts-ZIP erneut in den Cyberpunk-2077-Ordner und lass die Dateien ersetzen.",
    ["Mod files"] = "Mod-Dateien",
    ["Mod manager"] = "Mod-Manager",
    ["Moved into place from {folder}: {packs}."] = "Aus {folder} verschoben: {packs}.",
    ["No Local AI pack found. Download one from the mod’s Hugging Face page and extract it into the Cyberpunk 2077 folder, or choose another conversation provider."] = "Kein Paket für Local AI gefunden. Lade eines von der Hugging-Face-Seite des Mods herunter und entpacke es in den Cyberpunk-2077-Ordner, oder wähle einen anderen Gesprächsanbieter.",
    ["No problem found. Select a line to see what was checked."] = "Kein Problem gefunden. Wähle eine Zeile aus, um zu sehen, was geprüft wurde.",
    ["No sign of the conversation service in this session: the Runtime is missing or did not load. Extract the full install zip (AI-NPC-LLM-Companions) straight into the Cyberpunk 2077 folder (not into a new folder), check that red4ext/plugins/AiNpcCyberpunkMod is there, then restart the game. The full install is on the mod’s Nexus Mods page."] = "In dieser Sitzung gibt es keine Spur des Gesprächsdienstes: Die Runtime fehlt oder wurde nicht geladen. Entpacke das vollständige Installations-ZIP (AI-NPC-LLM-Companions) direkt in den Ordner Cyberpunk 2077 (nicht in einen neuen Ordner), prüfe, ob red4ext/plugins/AiNpcCyberpunkMod vorhanden ist, und starte dann das Spiel neu. Die vollständige Installation gibt es auf der Nexus-Mods-Seite des Mods.",
    ["None found: installed by hand."] = "Keine gefunden: von Hand installiert.",
    ["None installed. They are optional."] = "Keine installiert. Sie sind optional.",
    ["Not needed: Local AI and the voice run on this PC."] = "Nicht nötig: Local AI und Stimme laufen auf diesem PC.",
    ["Not used"] = "Nicht verwendet",
    ["Not your conversation provider. Choose it in Settings > Conversation provider."] = "Nicht dein Gesprächsanbieter. Wähle ihn unter Einstellungen > Gesprächsanbieter.",
    ["Note"] = "Hinweis",
    ["OK"] = "OK",
    ["Optional packs"] = "Optionale Pakete",
    ["Problem"] = "Problem",
    ["Problems found: {count}. Select a line marked Problem to read what to do."] = "Probleme gefunden: {count}. Wähle eine mit Problem markierte Zeile aus, um zu lesen, was zu tun ist.",
    ["RED4ext is not loaded. Install it from Nexus Mods, then restart the game. It also starts the conversation service."] = "RED4ext ist nicht geladen. Installiere es über Nexus Mods und starte das Spiel neu. Es startet außerdem den Gesprächsdienst.",
    ["Reached {host}."] = "{host} erreicht.",
    ["Scripts and Runtime"] = "Scripts und Runtime",
    ["Scripts {scripts} and Runtime {runtime}."] = "Scripts {scripts} und Runtime {runtime}.",
    ["Scripts {scripts} on Runtime base {runtime}."] = "Scripts {scripts} auf Runtime-Basis {runtime}.",
    ["These Scripts {scripts} need the Runtime base {required} or newer, and your Runtime is {runtime}. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Diese Scripts {scripts} benötigen die Runtime-Basis {required} oder neuer, und deine Runtime ist {runtime}. Entpacke das vollständige Installations-ZIP (AI-NPC-LLM-Companions, auf Nexus Mods) in den Ordner Cyberpunk 2077 und starte dann das Spiel neu.",
    ["The Runtime is older than {required}. Get the full install zip."] = "Die Runtime ist älter als {required}. Hol das Komplett-ZIP.",
    ["Setup check"] = "Installationsprüfung",
    ["Some mod files are missing. Extract the update zip again. See Help in Settings."] = "Mod-Dateien fehlen. Entpacke das Update-ZIP erneut. Siehe Hilfe in den Einstellungen.",
    ["Some pack files could not be moved into place because different files are already there. Extract the pack into the Cyberpunk 2077 folder again and let it replace the files."] = "Einige Paketdateien konnten nicht verschoben werden, weil dort bereits andere Dateien liegen. Entpacke das Paket erneut in den Cyberpunk-2077-Ordner und lass die Dateien ersetzen.",
    ["The Runtime is incomplete ({code}). Extract the full install zip (AI-NPC-LLM-Companions) into the Cyberpunk 2077 folder again and let it replace the files, then restart the game."] = "Die Runtime ist unvollständig ({code}). Entpacke das vollständige Installations-ZIP (AI-NPC-LLM-Companions) erneut in den Ordner Cyberpunk 2077 und lass die Dateien ersetzen, dann starte das Spiel neu.",
    ["The settings file of the launcher, launcher.ini, is missing from red4ext/plugins/AiNpcCyberpunkMod, so the game cannot start the conversation service. Extract the full install zip (AI-NPC-LLM-Companions) straight into the Cyberpunk 2077 folder again (by hand, also with Vortex) and let it replace the files, then restart the game."] = "Die Einstellungsdatei des Starters, launcher.ini, fehlt in red4ext/plugins/AiNpcCyberpunkMod, deshalb kann das Spiel den Gesprächsdienst nicht starten. Entpacke das vollständige Installations-ZIP (AI-NPC-LLM-Companions) erneut direkt in den Ordner Cyberpunk 2077 (von Hand, auch mit Vortex) und lass die Dateien ersetzen, dann starte das Spiel neu.",
    ["The conversation service cannot reach the internet. See Help in Settings."] = "Gesprächsdienst ohne Internetverbindung. Siehe Hilfe in den Einstellungen.",
    ["The conversation service cannot reach {host}. Allow Node.js through your firewall or antivirus (Windows asks once; choose Allow), check your internet, then restart the game."] = "Der Gesprächsdienst kann {host} nicht erreichen. Erlaube Node.js in deiner Firewall oder deinem Virenschutz (Windows fragt einmal nach; wähle Zugriff zulassen), prüfe deine Internetverbindung und starte dann das Spiel neu.",
    ["The conversation service could not start ({code}). Restart the game. If it happens again, generate a report below and send it."] = "Der Gesprächsdienst konnte nicht starten ({code}). Starte das Spiel neu. Tritt es erneut auf, erzeuge unten einen Bericht und schicke ihn ab.",
    ["The conversation service did not start. Is the Runtime installed? See Help in Settings."] = "Gesprächsdienst nicht gestartet. Ist die Runtime installiert? Siehe Hilfe in den Einstellungen.",
    ["The game version could not be read."] = "Die Spielversion konnte nicht gelesen werden.",
    ["This PC cannot look up {host}. Check your internet connection, then restart the game."] = "Dieser PC kann {host} nicht auflösen. Prüfe deine Internetverbindung und starte dann das Spiel neu.",
    ["Open r6/logs/redscript_rCURRENT.log. A mod it names is why the scripts did not load."] = "Öffne r6/logs/redscript_rCURRENT.log. Ein dort genannter Mod blockiert die Skripte.",
    ["This mod’s scripts did not load. Open r6/logs/redscript_rCURRENT.log. If the error names another mod, that mod is the problem. Missing or old Codeware or redscript, or a game version other than {game}, can also cause it."] = "Die Skripte dieses Mods wurden nicht geladen. Öffne r6/logs/redscript_rCURRENT.log. Nennt der Fehler einen anderen Mod, ist dieser das Problem. Auch ein fehlendes oder veraltetes Codeware oder redscript sowie eine andere Spielversion als {game} kann die Ursache sein.",
    ["Missing: {names}. Install them and restart the game."] = "Fehlt: {names}. Installiere sie und starte das Spiel neu.",
    ["Install or update: {names}. Then restart the game."] = "Installiere oder aktualisiere: {names}. Dann neu starten.",
    ["Codeware is too old. Update it from Nexus Mods, then restart the game."] = "Codeware ist zu alt. Aktualisiere es über Nexus Mods und starte das Spiel neu.",
    ["Version {version}."] = "Version {version}.",
    ["Version {version}. The mod is tested on {game} only, so some things may not work."] = "Version {version}. Der Mod wurde nur mit {game} getestet, daher funktionieren manche Dinge eventuell nicht.",
    ["Version {version}. These files are the mod build for game {build}. Extract the full install zip made for game {game}, from the mod’s Nexus Mods page, into the Cyberpunk 2077 folder, then restart the game."] = "Version {version}. Diese Dateien sind der Mod-Build für das Spiel {build}. Entpacke das vollständige Installations-ZIP für das Spiel {game} von der Nexus-Mods-Seite des Mods in den Ordner Cyberpunk 2077 und starte danach das Spiel neu.",
    ["Vortex. Install the optional packs by hand into the Cyberpunk 2077 folder, as the install steps say. Install the full install zip as one mod and update that mod with each new full install zip."] = "Vortex. Installiere die optionalen Pakete von Hand in den Ordner Cyberpunk 2077, wie es in den Installationsschritten steht. Installiere das vollständige Installations-ZIP als einen Mod und aktualisiere diesen Mod bei jedem neuen vollständigen Installations-ZIP.",
    ["{name} is missing. Install it from Nexus Mods, then restart the game."] = "{name} fehlt. Installiere es über Nexus Mods und starte das Spiel neu.",
    ["{name}, {memory} GB of video memory."] = "{name}, {memory} GB Videospeicher.",
    ["{packs} is one folder too deep, in {folder}. Restart the game and the mod moves it into place. If it is still there afterwards, move the red4ext folder inside it into the Cyberpunk 2077 folder."] = "{packs} liegt einen Ordner zu tief, in {folder}. Starte das Spiel neu, dann verschiebt der Mod es an die richtige Stelle. Liegt es danach noch dort, verschiebe den red4ext-Ordner darin in den Cyberpunk-2077-Ordner.",
    ["Add an endpoint URL and a model ID first."] = "Füge zuerst eine Endpunkt-URL und eine Modell-ID hinzu.",
    ["Convai: the custom provider is not set up yet"] = "Convai: eigener Anbieter noch nicht eingerichtet",
    ["Copy the base URL from your provider, for example https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 or http://localhost:11434/v1 (Ollama). It is read from the clipboard once and saved on this computer.\n\nOnly this computer and your home network may use http://. You can also fill in endpoint=, model= and api-key= in player-custom-endpoint.txt in the conversation service folder.\n\nNothing is sent until you choose this provider or press Test connection."] = "Kopiere die Basis-URL deines Anbieters, zum Beispiel https://openrouter.ai/api/v1, https://nano-gpt.com/api/v1 oder http://localhost:11434/v1 (Ollama). Sie wird einmal aus der Zwischenablage gelesen und nur auf diesem Computer gespeichert.\n\nNur dieser Computer und dein Heimnetzwerk dürfen http:// verwenden. Du kannst auch endpoint=, model= und api-key= in player-custom-endpoint.txt im Ordner des Gesprächsdienstes eintragen.\n\nEs wird nichts gesendet, bis du diesen Anbieter wählst oder Verbindung testen drückst.",
    ["Copy the model ID from your provider first, for example meta-llama/llama-3.1-8b-instruct on OpenRouter or llama3.2 on Ollama. It is read from the clipboard once and saved on this computer."] = "Kopiere zuerst die Modell-ID deines Anbieters, zum Beispiel meta-llama/llama-3.1-8b-instruct bei OpenRouter oder llama3.2 bei Ollama. Sie wird einmal aus der Zwischenablage gelesen und nur auf diesem Computer gespeichert.",
    ["Copy your API key from your provider first. It is read from the clipboard once and saved on this computer only. A server on your own computer, such as Ollama or LM Studio, usually needs no key."] = "Kopiere zuerst deinen API-Schlüssel von deinem Anbieter. Er wird einmal aus der Zwischenablage gelesen und nur auf diesem Computer gespeichert. Ein Server auf deinem eigenen Computer, etwa Ollama oder LM Studio, braucht meist keinen Schlüssel.",
    ["Custom (OpenAI-compatible)"] = "Eigener (OpenAI-kompatibel)",
    ["Custom API key"] = "Eigener API-Schlüssel",
    ["Custom endpoint URL"] = "Eigene Endpunkt-URL",
    ["Custom model ID"] = "Eigene Modell-ID",
    ["Custom provider replies are spoken by a local voice instead of the Convai cloud voice."] = "Antworten des eigenen Anbieters: lokale Stimme statt Convai-Cloud-Stimme.",
    ["Custom: key not accepted"] = "Eigener: Schlüssel nicht akzeptiert",
    ["Custom: model unavailable"] = "Eigener: Modell nicht verfügbar",
    ["Custom: out of credits"] = "Eigener: kein Guthaben mehr",
    ["Custom: rate limited for now"] = "Eigener: vorerst gedrosselt",
    ["Deletes the saved endpoint URL. The custom provider needs one to answer."] = "Löscht die gespeicherte Endpunkt-URL. Der eigene Anbieter braucht sie, um zu antworten.",
    ["Deletes the saved key. Replies from the custom provider are then asked for without a key."] = "Löscht den gespeicherten Schlüssel. Antworten des eigenen Anbieters werden dann ohne Schlüssel angefragt.",
    ["Deletes the saved model ID. The custom provider needs one to answer."] = "Löscht die gespeicherte Modell-ID. Der eigene Anbieter braucht sie, um zu antworten.",
    ["Failed"] = "Fehlgeschlagen",
    ["It answered in {ms} ms."] = "Antwort nach {ms} ms.",
    ["It could not be saved."] = "Nicht gespeichert.",
    ["Model ID: {model}"] = "Modell-ID: {model}",
    ["Only https:// works outside this computer and your home network."] = "Außerhalb dieses Computers und deines Heimnetzes funktioniert nur https://.",
    ["Paste API key"] = "Schlüssel einfügen",
    ["Paste endpoint URL"] = "URL einfügen",
    ["Paste model ID"] = "Modell-ID einfügen",
    ["Sends one tiny message to your endpoint with the saved model ID and key, and shows how it answered. It uses next to nothing of your credits."] = "Sendet eine winzige Testnachricht an deinen Endpunkt mit gespeicherter Modell-ID und Schlüssel und zeigt die Antwort. Kostet kaum Guthaben.",
    ["Test"] = "Testen",
    ["Test connection"] = "Verbindung testen",
    ["Testing the connection…"] = "Verbindung wird getestet…",
    ["Testing…"] = "Testen…",
    ["That is too long."] = "Das ist zu lang.",
    ["That was not accepted."] = "Das wurde nicht akzeptiert.",
    ["The account is out of credits. Add credits with your provider."] = "Das Konto hat kein Guthaben mehr. Lade es bei deinem Anbieter auf.",
    ["The address must start with https:// or http://."] = "Die Adresse muss mit https:// oder http:// beginnen.",
    ["The address sends you somewhere else. Use the final address from your provider."] = "Die Adresse leitet woanders hin. Verwende die endgültige Adresse deines Anbieters.",
    ["That address is a web page, not the API. For OpenRouter use https://openrouter.ai/api/v1."] = "Diese Adresse ist eine Webseite, nicht die API. Für OpenRouter verwende https://openrouter.ai/api/v1.",
    ["That address is a web page, not the API. Use the API address from your provider."] = "Diese Adresse ist eine Webseite, nicht die API. Verwende die API-Adresse deines Anbieters.",
    ["A model ID is a short name like that, not a web address."] = "Eine Modell-ID ist ein kurzer Name wie dieser, keine Web-Adresse.",
    ["The clipboard does not hold a model ID."] = "Die Zwischenablage enthält keine Modell-ID.",
    ["The clipboard does not hold a web address."] = "Die Zwischenablage enthält keine Web-Adresse.",
    ["The clipboard does not hold an API key."] = "Die Zwischenablage enthält keinen API-Schlüssel.",
    ["The clipboard is empty. Copy it first."] = "Die Zwischenablage ist leer. Kopiere sie zuerst.",
    ["The connection test failed."] = "Der Verbindungstest schlug fehl.",
    ["The connection works. The endpoint accepted your model and key."] = "Die Verbindung klappt. Der Endpunkt akzeptiert Modell und Schlüssel.",
    ["The conversation service is not running, so nothing can be tested. Restart the game."] = "Der Gesprächsdienst läuft nicht, daher kann nichts getestet werden. Starte das Spiel neu.",
    ["The custom provider did not accept your key. Check it in Settings > Conversation provider."] = "Eigener Anbieter lehnt den Schlüssel ab. Prüfe ihn unter Einstellungen > Gesprächsanbieter.",
    ["The custom provider did not answer. Check its address in Settings, or try again."] = "Eigener Anbieter reagiert nicht. Prüfe die Adresse in den Einstellungen oder versuche es erneut.",
    ["The custom provider does not know that model ID. Check it in Settings."] = "Eigener Anbieter kennt diese Modell-ID nicht. Prüfe sie in den Einstellungen.",
    ["The custom provider is not set up, so Convai is used. Add its URL and model ID in Settings."] = "Eigener Anbieter nicht eingerichtet: Convai aktiv. Gib URL und Modell-ID in den Einstellungen an.",
    ["The custom provider is rate limiting you. Try again in a moment."] = "Der eigene Anbieter drosselt gerade. Versuche es gleich erneut.",
    ["The custom provider says your account is out of credits. Add credits there, then try again."] = "Eigener Anbieter: kein Guthaben mehr. Dort aufladen und erneut versuchen.",
    ["The endpoint URL was removed."] = "Die Endpunkt-URL wurde entfernt.",
    ["The endpoint answered with no text. Check the model ID."] = "Der Endpunkt hat ohne Text geantwortet. Prüfe die Modell-ID.",
    ["The endpoint did not accept your API key."] = "Der Endpunkt akzeptiert deinen API-Schlüssel nicht.",
    ["The endpoint did not answer. Check its address."] = "Der Endpunkt hat nicht geantwortet. Prüfe die Adresse.",
    ["The endpoint does not know that model ID."] = "Der Endpunkt kennt diese Modell-ID nicht.",
    ["The endpoint is rate limiting you. Try again in a moment."] = "Der Endpunkt drosselt dich gerade. Versuche es gleich noch einmal.",
    ["The endpoint is rate limiting you. Wait about {seconds} seconds, then try again."] = "Der Endpunkt drosselt dich. Warte etwa {seconds} Sekunden und versuche es erneut.",
    ["The endpoint refused the request. Check the model ID and the address."] = "Der Endpunkt hat die Anfrage abgelehnt. Prüfe Modell-ID und Adresse.",
    ["The endpoint reported an error on its side. Try again in a moment."] = "Der Endpunkt meldet einen Fehler auf seiner Seite. Versuche es gleich erneut.",
    ["The endpoint took too long to answer."] = "Der Endpunkt antwortete zu spät.",
    ["The model ID was removed."] = "Die Modell-ID wurde entfernt.",
    ["The provider said: {detail}"] = "Der Anbieter meldet: {detail}",
    ["This address is not encrypted, which is fine on your own computer or home network."] = "Diese Adresse ist nicht verschlüsselt. Auf deinem Computer oder Heimnetz ist das in Ordnung.",
    ["Use the base URL only: no password, query or #."] = "Nur die Basis-URL: ohne Passwort, Abfrage oder #.",
    ["Waiting for the endpoint to answer…"] = "Warte auf Antwort vom Endpunkt…",
    ["Custom: free daily limit reached"] = "Eigener: kostenloses Tageslimit erreicht",
    ["New address saved. Paste your API key again for it."] = "Neue Adresse gespeichert. Füge dafür deinen API-Schlüssel erneut ein.",
    ["The free daily limit for this model was reached. It resets at {time}."] = "Kostenloses Tageslimit für dieses Modell erreicht. Reset um {time}.",
    ["The free daily limit for this model was reached. Try again after it resets."] = "Kostenloses Tageslimit für dieses Modell erreicht. Versuche es nach dem Reset erneut.",
    ["This model spends its reply on thinking. Choose a non-reasoning model in Settings."] = "Dieses Modell denkt statt zu antworten. Wähle unter Einstellungen ein Non-Reasoning-Modell.",
    ["All"] = "Alle",
    ["Also changed: {names}."] = "Außerdem geändert: {names}.",
    ["Choose any character from the list below. They do not need to be in your current party."] = "Wähle einen beliebigen Charakter aus der Liste unten. Er muss nicht in deiner aktuellen Gruppe sein.",
    ["Defaults restored."] = "Standardwerte wiederhergestellt.",
    ["Drag the slider, or press left and right, to turn the page."] = "Zieh den Regler oder drücke links und rechts, um die Seite zu wechseln.",
    ["How loud the mod’s voices are, for companions, characters and V’s typed lines. 100 is the normal level.\n\nAbove 100 the voices get louder, with a limiter so they do not crackle. The game’s own dialogue and sounds do not change.\n\nThe next reply uses it."] = "Wie laut die Stimmen des Mods sind, bei Begleitern, Figuren und V‑Sätzen, die du tippst. 100 ist die normale Lautstärke.\n\nÜber 100 werden die Stimmen lauter, mit einem Limiter, damit sie nicht knacken. Die Dialoge und Geräusche des Spiels bleiben unverändert.\n\nDie nächste Antwort nutzt den Wert.",
    ["Not available right now."] = "Im Moment nicht verfügbar.",
    ["Open Settings to restore its defaults."] = "Öffne die Einstellungen, um die Standardwerte wiederherzustellen.",
    ["Page"] = "Seite",
    ["Show only the models whose name starts with this letter."] = "Zeigt nur die Modelle, deren Name mit diesem Buchstaben beginnt.",
    ["Starts with"] = "Beginnt mit",
    ["Open AI NPC Cyberpunk Mod in the Mods list."] = "Öffne AI NPC Cyberpunk Mod in der Mods-Liste.",
    ["The settings could not be saved. Nothing was changed."] = "Die Einstellungen konnten nicht gespeichert werden. Nichts wurde geändert.",
    ["Privacy"] = "Datenschutz",
    ["Send error reports automatically"] = "Fehlerberichte automatisch senden",
    ["Error reports go to the developer automatically. Turn them off in Settings > Privacy."] = "Fehlerberichte gehen automatisch an den Entwickler. Aus: Einstellungen > Datenschutz.",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI"] = "Die Begleiterverwaltung benötigt Mod Configuration Menu 0.10.5+ oder Native Settings UI",
    ["Update Mod Configuration Menu to 0.10.5 or newer, or install Native Settings UI"] = "Aktualisiere Mod Configuration Menu auf 0.10.5 oder neuer oder installiere Native Settings UI",
    ["Stand up to open the Companion Manager"] = "Steh auf, um die Begleiterverwaltung zu öffnen",
    ["The Companion Manager needs Mod Configuration Menu 0.10.5 or newer, or Native Settings UI {nsui} or newer. Either one is enough. Install one from Nexus Mods, then restart the game."] = "Die Begleiterverwaltung benötigt Mod Configuration Menu 0.10.5 oder neuer oder Native Settings UI {nsui} oder neuer. Eins davon reicht. Installiere eines davon über Nexus Mods und starte das Spiel neu.",
    ["Mod Configuration Menu is too old. Update it to 0.10.5 or newer, or install Native Settings UI, then restart the game."] = "Mod Configuration Menu ist zu alt. Aktualisiere es auf 0.10.5 oder neuer oder installiere Native Settings UI und starte dann das Spiel neu.",
    ["Previous page"] = "Vorherige Seite",
    ["Next page"] = "Nächste Seite",
    ["Starts with: {letter}"] = "Beginnt mit: {letter}",
    ["Characters and party"] = "Charaktere und Gruppe",
    ["Load a save first"] = "Erst Spielstand laden",
    ["Inviting characters and managing your party need a loaded game."] = "Charaktere einladen und die Gruppe verwalten geht nur in einem geladenen Spiel.",
    ["Voxtral (recommended)"] = "Voxtral (empfohlen)",
    ["Defaults"] = "Standard",
    ["Press Confirm to put every setting back to its default."] = "Drücke Bestätigen, um jede Einstellung auf ihren Standardwert zurückzusetzen.",
    ["Local AI stopped working and was restarted."] = "Local AI hat nicht mehr funktioniert und wurde neu gestartet.",
    ["Local AI runs mostly on your processor here, so replies will be slow."] = "Local AI läuft hier hauptsächlich auf deinem Prozessor, deshalb sind die Antworten langsam.",
    ["Changes this mod’s menus and notices only.\n\nCharacter voices and the language you talk in are separate. The microphone uses this language as a hint for non-English speech."] = "Ändert nur die Menüs und Hinweise dieses Mods.\n\nStimmen der Charaktere und die Sprache, in der du sprichst, sind getrennt. Das Mikrofon nutzt diese Sprache als Hinweis für Sprache, die nicht Englisch ist.",
    ["Voxtral stops speaking; companion replies show as text until a key is saved."] = "Voxtral spricht nicht mehr; die Antworten der Begleiter erscheinen als Text, bis ein Schlüssel gespeichert ist.",
    ["Conversations go back to Convai free tier."] = "Gespräche kehren zu Convai (kostenloser Tarif) zurück.",
    ["Deletes the saved key."] = "Löscht den gespeicherten Schlüssel.",
    ["Nothing you use now depends on it."] = "Nichts, was du gerade nutzt, hängt davon ab.",
    ["The Convai cloud voice cannot use Natural speech, so it was turned off."] = "Die Convai-Cloud-Stimme kann keine Natürliche Sprechweise nutzen, deshalb wurde sie ausgeschaltet.",
    ["Custom endpoint"] = "Eigener Endpunkt",
    ["Speaks up often"] = "Meldet sich oft",
    ["Speaks up rarely"] = "Meldet sich selten",
    ["The address, API key and model ID of your OpenAI-compatible provider, and a connection test. Used when Custom is the Conversation provider."] = "Adresse, API-Schlüssel und Modell-ID deines OpenAI-kompatiblen Anbieters sowie ein Verbindungstest. Wird verwendet, wenn Eigener der Gesprächsanbieter ist.",
    ["V’s voice switches from Voxtral to Pocket."] = "Vs Stimme wechselt von Voxtral zu Pocket.",
    ["OmniVoice · needs Omni pack"] = "OmniVoice · Omni-Paket fehlt",
    ["OmniVoice · needs Omni voice"] = "OmniVoice · Omni-Stimme fehlt",
    ["Requires the Companion voices to be an OmniVoice choice"] = "Erfordert, dass die Begleiterstimmen eine OmniVoice-Option sind",
    ["V’s voice switches from OmniVoice to Pocket."] = "Vs Stimme wechselt von OmniVoice zu Pocket.",
    ["V’s voice"] = "Stimme von V",
    ["V (male voice)"] = "V (männliche Stimme)",
    ["V (female voice)"] = "V (weibliche Stimme)",
    ["Used for V’s typed lines: Pocket, OmniVoice and the Voxtral cloud voice copy it."] = "Verwendet für Vs getippte Zeilen: Pocket, OmniVoice und die Voxtral-Cloudstimme kopieren sie.",
    ["V speaks with the voice of your installed V voice mod, or the shipped V voice."] = "V spricht mit der Stimme deines installierten V-Stimmen-Mods oder mit der Originalstimme von V.",
    ["Remove the voice clip? V goes back to the voice of your installed V voice mod, or the shipped V voice."] = "Sprachclip entfernen? V kehrt zur Stimme deines installierten V-Stimmen-Mods oder zur Originalstimme zurück.",
    ["OmniVoice needs an NVIDIA graphics card, and this PC has none that works. Replies show as text. Choose Pocket in Settings to hear voices."] = "OmniVoice braucht eine NVIDIA-Grafikkarte, und in diesem PC ist keine funktionierende vorhanden. Antworten erscheinen als Text. Wähle in den Einstellungen Pocket, um Stimmen zu hören.",
    ["OmniVoice needs an NVIDIA graphics card, and this PC has none that works. Companions are using {voice} instead."] = "OmniVoice braucht eine NVIDIA-Grafikkarte, und in diesem PC ist keine funktionierende vorhanden. Deine Begleiter verwenden stattdessen {voice}.",
    ["OmniVoice needs NVIDIA"] = "OmniVoice braucht NVIDIA",
    ["This PC has no NVIDIA graphics card, which OmniVoice needs. OmniVoice will not start here. Choose Pocket to hear voices."] = "Dieser PC hat keine NVIDIA-Grafikkarte, die OmniVoice braucht. OmniVoice startet hier nicht. Wähle Pocket, um Stimmen zu hören.",
    ["{voice} · needs NVIDIA card"] = "{voice} · braucht NVIDIA-Karte",
    ["{language} replies show as text: the {language} multilingual pack is missing."] = "Antworten auf {language} erscheinen als Text: Das mehrsprachige {language}-Paket fehlt.",
    ["French"] = "Französisch",
    ["Italian"] = "Italienisch",
    ["German"] = "Deutsch",
    ["Spanish"] = "Spanisch",
    ["Portuguese"] = "Portugiesisch",
    ["OmniVoice needs more graphics memory than is free next to the game. Pocket is used."] = "OmniVoice braucht mehr freien Grafikspeicher neben dem Spiel. Pocket wird genutzt.",
    ["Windows ran out of memory for the voice. A larger paging file or closing other apps helps."] = "Windows fehlt Speicher für die Stimme. Hilft: Auslagerungsdatei vergrößern, Apps schließen.",
    ["OmniVoice needs 12 GB"] = "OmniVoice braucht 12 GB",
    ["{voice} · needs 12 GB card"] = "{voice} · braucht 12-GB-Karte",
    ["The graphics card in this PC has less than the 12 GB OmniVoice needs next to the game. If it cannot start, Pocket is used. Choose Pocket to skip the wait."] = "Die Grafikkarte in diesem PC hat neben dem Spiel weniger als die 12 GB, die OmniVoice braucht. Startet OmniVoice nicht, wird Pocket verwendet. Wähle Pocket, um die Wartezeit zu überspringen.",
    ["Forget all memories ({count} characters)"] = "Alle Erinnerungen vergessen ({count} Charaktere)",
    ["Dynamic info"] = "Live-Infos",
    ["What the game tells each character about this moment. A character mentions it only when it fits the talk.\n\nAn off kind is left out of every conversation provider (Convai, Mistral, Local AI and Custom)."] = "Was das Spiel jedem Charakter über diesen Moment erzählt. Ein Charakter erwähnt es nur, wenn es zum Gespräch passt.\n\nEine ausgeschaltete Info wird bei allen Gesprächsanbietern (Convai, Mistral, Local AI und Eigener) weggelassen.",
    ["Location"] = "Ort",
    ["Where V is: the district, and V’s apartment or the named place when the game says so.\n\nOff: characters are not told where you are, and the mod stops reading it from the game. The picture Convai gets of what V sees, and an add-on’s own text, are not affected."] = "Wo V ist: das Viertel sowie V’s Wohnung oder der genannte Ort, wenn das Spiel es angibt.\n\nAus: Die Charaktere erfahren nicht, wo du bist, und der Mod liest es nicht mehr aus dem Spiel aus. Das Bild, das Convai davon bekommt, was V sieht, und der eigene Text eines Add-ons bleiben unberührt.",
    ["Time and weather"] = "Uhrzeit und Wetter",
    ["The hour of the day and the weather in Night City.\n\nOff: nobody is told the time or the weather, and the mod stops reading them from the game."] = "Die Tageszeit und das Wetter in Night City.\n\nAus: Niemand erfährt die Uhrzeit oder das Wetter, und der Mod liest sie nicht mehr aus dem Spiel aus.",
    ["Company and vehicle"] = "Begleitung und Fahrzeug",
    ["Who else is with V, whether V is on foot or in a vehicle, and what a companion is doing beside V.\n\nOff: none of this is sent, and the mod stops reading it from the game."] = "Wer sonst bei V ist, ob V zu Fuß oder im Fahrzeug unterwegs ist und was ein Begleiter neben V tut.\n\nAus: Davon wird nichts gesendet, und der Mod liest es nicht mehr aus dem Spiel aus.",
    ["Health, heat and fights"] = "Gesundheit, Fahndung und Kämpfe",
    ["V’s health, the police heat on V, and the last fight V was in.\n\nOff: none of this is sent, and the mod stops reading it from the game."] = "Vs Gesundheit, die Fahndung der Polizei gegen V und der letzte Kampf, in dem V war.\n\nAus: Davon wird nichts gesendet, und der Mod liest es nicht mehr aus dem Spiel aus.",
    ["V’s money"] = "Geld von V",
    ["A rough idea of how many eddies V has: nearly broke, short, comfortable or rich.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "Eine grobe Vorstellung, wie viele Eddies V hat: fast pleite, knapp, gut situiert oder reich.\n\nAus: Das wird nicht gesendet, und der Mod liest es nicht mehr aus dem Spiel aus.",
    ["V’s gear and clothes"] = "Ausrüstung und Kleidung",
    ["What V wears and carries: clothes, weapons and cyberware that can be seen.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "Was V trägt und bei sich hat: Kleidung, Waffen und sichtbare Cyberware.\n\nAus: Das wird nicht gesendet, und der Mod liest es nicht mehr aus dem Spiel aus.",
    ["V’s gender and lifepath"] = "Geschlecht und Lebensweg",
    ["Whether V is a woman or a man, and V’s lifepath: Nomad, Street Kid or Corpo.\n\nOff: it is not sent with a turn, and the mod stops reading it for that. Your story’s own facts may still reflect your lifepath."] = "Ob V eine Frau oder ein Mann ist und V’s Lebensweg: Nomade, Straßenkind oder Konzerner.\n\nAus: Das wird bei keiner Gesprächsrunde gesendet, und der Mod liest es dafür nicht mehr aus dem Spiel aus. Die Fakten deiner Geschichte können trotzdem deinen Lebensweg widerspiegeln.",
    ["Quest and journal"] = "Auftrag und Tagebuch",
    ["V’s tracked quest and its objectives, the jobs V has open and the journal history.\n\nWhat each character knows about your story stays on.\n\nOff: none of this is sent. The mod stops scanning the journal for it, unless Johnny’s remarks are on."] = "Der verfolgte Auftrag und seine Ziele, die offenen Jobs von V und der Tagebuchverlauf.\n\nWas jeder Charakter über deine Geschichte weiß, bleibt aktiv.\n\nAus: Davon wird nichts gesendet. Der Mod sucht im Tagebuch nicht mehr danach, es sei denn, Johnnys Bemerkungen sind an.",
    ["Recent game dialogue"] = "Letzte Dialoge",
    ["The last lines spoken in scenes and V’s chosen replies, so a character can pick up from what was just said.\n\nOff: they are not sent."] = "Die letzten Zeilen aus den Szenen und Vs gewählte Antworten, damit ein Charakter an das Gesagte anknüpfen kann.\n\nAus: Sie werden nicht gesendet.",
    ["The Runtime is out of date. Get the full install zip."] = "Die Runtime ist veraltet. Hol das vollständige Installations-ZIP.",
    ["The Scripts and Runtime do not match. Update whichever is older. See Help in Settings."] = "Scripts und Runtime passen nicht. Aktualisiere das ältere. Siehe Hilfe in den Einstellungen.",
    ["Scripts {scripts} and Runtime {runtime} do not match: the Runtime is out of date. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Scripts {scripts} und Runtime {runtime} passen nicht zusammen: Die Runtime ist veraltet. Entpacke das vollständige Installations-ZIP (AI-NPC-LLM-Companions, auf Nexus Mods) in den Ordner Cyberpunk 2077 und starte dann das Spiel neu.",
    ["Scripts {scripts} and Runtime {runtime} do not match. If the Scripts are older, install the update zip from Nexus Mods. If the Runtime is older, install the full install zip (AI-NPC-LLM-Companions). Extract into the Cyberpunk 2077 folder, then restart the game."] = "Scripts {scripts} und Runtime {runtime} passen nicht zusammen. Sind die Scripts älter, installiere das Update-ZIP von Nexus Mods. Ist die Runtime älter, installiere das vollständige Installations-ZIP (AI-NPC-LLM-Companions). Entpacke in den Ordner Cyberpunk 2077 und starte dann das Spiel neu.",
    ["The conversation service did not answer the setup check, so its Runtime is probably older than these Scripts. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Der Gesprächsdienst hat auf die Installationsprüfung nicht geantwortet, daher ist seine Runtime wahrscheinlich älter als diese Scripts. Entpacke das vollständige Installations-ZIP (AI-NPC-LLM-Companions, auf Nexus Mods) in den Ordner Cyberpunk 2077 und starte dann das Spiel neu.",
    ["The Runtime update from {from} to {to} was never applied, so some Runtime files are old. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Das Runtime-Update von {from} auf {to} wurde nie angewendet, daher sind einige Runtime-Dateien alt. Entpacke das vollständige Installations-ZIP (AI-NPC-LLM-Companions, auf Nexus Mods) in den Ordner Cyberpunk 2077 und starte dann das Spiel neu.",
    ["Runtime files are old. Get the full install zip."] = "Runtime-Dateien sind alt. Hol das Komplett-ZIP.",
    ["Character unavailable in this game installation."] = "Charakter in dieser Spielinstallation nicht verfügbar.",
    ["Message could not be delivered. Please try again."] = "Nachricht nicht gesendet. Bitte erneut versuchen.",
    ["The conversation service could not reply. Please try again."] = "Der Gesprächsdienst konnte nicht antworten. Bitte erneut versuchen.",
    ["Voice conversation failed. Check your microphone and try again."] = "Sprachchat fehlgeschlagen. Prüfe dein Mikrofon und versuche es erneut.",
    ["{name} is one of your own characters. They need Mistral, Local AI or Custom: choose one under Conversation provider in the settings."] = "{name} ist einer deiner eigenen Charaktere. Die Figur braucht Mistral, Local AI oder Custom: Wähle in den Einstellungen unter „Gesprächsanbieter“ eine davon aus.",
    ["Companions now and then pause, hesitate, laugh or sigh, as their personality would. It stays rare.\n\nOmniVoice can voice laughs and sighs; the other voices only add pauses.\n\nNot available with Convai’s cloud voice: choosing it turns this off, and turning this on switches the voice to Pocket."] = "Begleiter pausieren, zögern, lachen oder seufzen ab und zu, so wie es zu ihrer Persönlichkeit passt. Es bleibt selten.\n\nOmniVoice kann Lachen und Seufzer sprechen; die anderen Stimmen fügen nur Pausen hinzu.\n\nNicht verfügbar mit der Convai-Cloud-Stimme: Sie zu wählen schaltet dies aus, und dies einzuschalten wechselt die Stimme zu Pocket.",
    ["For testing and bug reports; leave it off for normal play.\n\nShows routine popups, writes a movement trace in the mod’s runtime folder, logs gesture decisions and adds itself to support reports.\n\nFailures, preparation progress and joined notices stay visible when it is off."] = "Für Tests und Fehlerberichte; für normales Spielen ausgeschaltet lassen.\n\nZeigt Routine-Popups, schreibt eine Bewegungsspur in den Laufzeitordner des Mods, protokolliert Gestenentscheidungen und nimmt sich selbst in Supportberichte auf.\n\nFortschritt der Vorbereitung, Beitrittsmeldungen und Fehler bleiben auch bei ausgeschalteter Option sichtbar.",
    ["Pocket: the lightest, on your CPU, about 0.2 s to the first word.\n\nOmniVoice: richer, needs a capable GPU and its pack, 1 to 2.5 s.\n\nVoxtral: cloud voices with your Mistral key. The companions’ voice loads no local model; V’s typed lines follow V’s own voice setting.\n\nConvai: its own cloud voice. A voice that cannot run shows replies as text."] = "Pocket: die leichteste, läuft auf der CPU, das erste Wort nach etwa 0,2 s.\n\nOmniVoice: reicher, braucht eine starke GPU und sein Paket, 1 bis 2,5 s.\n\nVoxtral: Cloud-Stimmen mit deinem Mistral-Schlüssel. Die Stimme der Begleiter lädt kein lokales Modell; die getippten Zeilen von V folgen V’s Stimmeinstellung.\n\nConvai: eigene Cloud-Stimme. Eine Stimme, die nicht laufen kann, zeigt Antworten als Text.",
    ["The game’s own named characters, such as Judy, Jackie, Panam and Rogue, answer when you talk to them where they stand, with their own voice and memory.\n\nNothing else about them changes: they do not turn, move, gesture or follow, and stay quiet during scenes, quest conversations, fights and rides.\n\nTakes effect after you reload your save."] = "Die eigenen benannten Charaktere des Spiels, etwa Judy, Jackie, Panam und Rogue, antworten vor Ort, wenn du sie ansprichst, mit eigener Stimme und eigenem Gedächtnis.\n\nSonst ändert sich nichts: Sie drehen sich nicht, bewegen sich nicht, gestikulieren nicht und folgen dir nicht. Bei Szenen, Questgesprächen, Kämpfen und Fahrten bleiben sie still.\n\nWirkt, nachdem du deinen Spielstand neu lädst.",
    ["Mod Organizer 2. Files the mod creates go to its Overwrite folder; leave them there. Install the full install zip as one mod and update that mod with each new full install zip. Extract multilingual packs into that mod’s folder, not as new mods. Mention Mod Organizer 2 when you send a report."] = "Mod Organizer 2. Dateien, die der Mod erstellt, landen in seinem Overwrite-Ordner; lass sie dort. Installiere das vollständige Installations-ZIP als einen Mod und aktualisiere diesen Mod bei jedem neuen vollständigen Installations-ZIP. Entpacke mehrsprachige Pakete in den Ordner dieses Mods, nicht als neue Mods. Erwähne Mod Organizer 2, wenn du einen Bericht schickst.",
    ["With a mod manager: remove the old Scripts and Runtime mods, then install the full install zip as one mod."] = "Mit einem Mod-Manager: Entferne die alten Mods Scripts und Runtime und installiere dann das vollständige Installations-ZIP als einen Mod.",
    ["Some Runtime files are from a newer update than this Runtime says. Extract the full install zip (AI-NPC-LLM-Companions, on Nexus Mods) into the Cyberpunk 2077 folder again. Then restart the game."] = "Einige Runtime-Dateien stammen aus einem neueren Update, als diese Runtime angibt. Entpacke das vollständige Installations-ZIP (AI-NPC-LLM-Companions, auf Nexus Mods) erneut in den Ordner Cyberpunk 2077. Starte danach das Spiel neu.",
    ["Multilingual pack ({code})"] = "Mehrsprachiges Paket ({code})",
    ["PocketTTS model ({code})"] = "PocketTTS-Modell ({code})",
    ["Your typed lines are spoken out loud too, in the V voice that matches yours, then the companion answers. V’s line is always waited for, up to about 30 s without audio.\n\nPocket: on your processor, about 0.2 s (its own small model if the companions use another voice). Voxtral: cloud, with your Mistral key. OmniVoice: the companions’ GPU voice, a second more wait."] = "Getippte Zeilen werden auch laut gesprochen, mit der V-Stimme, die zu deiner passt, dann antwortet der Begleiter. Auf Vs Zeile wird immer gewartet, höchstens etwa 30 s ohne Ton.\n\nPocket: auf dem Prozessor, etwa 0,2 s (eigenes kleines Modell, falls die Begleiter anders klingen). Voxtral: Cloud mit deinem Mistral-Schlüssel. OmniVoice: GPU-Stimme der Begleiter, eine Sekunde Wartezeit mehr.",
    ["Edit characters’ bios, rules and memories, and the prompting for each AI option, in your browser.\n\nWorks with Mistral, Local AI and Custom, not Convai. Changes apply from the next reply."] = "Bearbeite in deinem Browser Biografien, Regeln und Erinnerungen der Charaktere sowie den Prompt für jede KI-Option.\n\nFunktioniert mit Mistral, Local AI und Eigener, nicht mit Convai. Änderungen gelten ab der nächsten Antwort.",
    ["Edit a character’s bio, speaking style, speaking rules and memories, and the prompting for each AI option, or make a character of your own, in your browser.\n\nWorks with Mistral, Local AI and Custom, not Convai. Changes apply from the next reply."] = "Bearbeite in deinem Browser Biografie, Sprechstil, Sprechregeln und Erinnerungen eines Charakters sowie den Prompt für jede KI-Option oder erstelle einen eigenen Charakter.\n\nFunktioniert mit Mistral, Local AI und Eigener, nicht mit Convai. Änderungen gelten ab der nächsten Antwort.",
    ["Custom: {model} at {host}"] = "Eigener: {model} bei {host}",
    ["Mistral"] = "Mistral",
    ["Local AI, Lite"] = "Local AI, Lite",
    ["Local AI, Standard"] = "Local AI, Standard",
    ["Local AI, Lite, Mature on"] = "Local AI, Lite, Inhalte für Erwachsene an",
    ["Local AI, Standard, Mature on"] = "Local AI, Standard, Inhalte für Erwachsene an",
    ["Heading of the output rules"] = "Überschrift der Ausgaberegeln",
    ["Heading of the example replies"] = "Überschrift der Beispielantworten",
    ["Heading of the format notes"] = "Überschrift der Formathinweise",
    ["Heading of the world and quest context"] = "Überschrift für Welt- und Quest-Kontext",
    ["Heading of what the character remembers"] = "Überschrift für das, woran sich der Charakter erinnert",
    ["Heading of the right-now facts"] = "Überschrift der Fakten zum Augenblick",
    ["Heading of the character’s own right-now facts"] = "Überschrift der eigenen Fakten zum Augenblick des Charakters",
    ["Heading of the notes for this turn"] = "Überschrift der Notizen für diese Runde",
    ["Heading of the things remembered about V"] = "Überschrift der Dinge, die über V gemerkt wurden",
    ["Opening line for a named character"] = "Eröffnungszeile für einen benannten Charakter",
    ["Opening line for an ordinary person"] = "Eröffnungszeile für eine normale Person",
    ["Closing line"] = "Schlusszeile",
    ["Closing line for a speaker with a reply length of its own"] = "Schlusszeile für einen Sprecher mit eigener Antwortlänge",
    ["Temperature"] = "Temperatur",
    ["Top P"] = "Top P",
    ["Repeat penalty"] = "Wiederholungsstrafe",
    ["Longest reply (in tokens)"] = "Längste Antwort (in Tokens)",
    ["Top K"] = "Top K",
    ["Min P"] = "Min P",
    ["Presence penalty"] = "Präsenzstrafe",
    ["Frequency penalty"] = "Häufigkeitsstrafe",
    ["Advanced parameters (JSON)"] = "Erweiterte Parameter (JSON)",
    ["Extra settings added to every reply, written as a JSON object, for example {example}. Use it for samplers that have no box above. A setting that has its own box above is refused. If a server refuses a setting, it is left out and the reply still comes."] = "Zusätzliche Einstellungen für jede Antwort, als JSON-Objekt geschrieben, zum Beispiel {example}. Gedacht für Sampler, die oben kein Feld haben. Eine Einstellung, die oben ein eigenes Feld hat, wird abgelehnt. Lehnt ein Server eine Einstellung ab, wird sie weggelassen, und die Antwort kommt trotzdem.",
    ["Mistral takes only the settings shown here. Top K, Min P and the advanced JSON are for Local AI and Custom models."] = "Mistral nimmt nur die hier gezeigten Einstellungen an. Top K, Min P und das erweiterte JSON gelten für Local AI und eigene Modelle.",
    ["Mistral does not take this setting."] = "Mistral nimmt diese Einstellung nicht an.",
    ["That is not valid JSON."] = "Das ist kein gültiges JSON.",
    ["This must be a JSON object, for example {example}."] = "Das muss ein JSON-Objekt sein, zum Beispiel {example}.",
    ["Too many keys. Keep {max} or fewer."] = "Zu viele Schlüssel. Bleib bei {max} oder weniger.",
    ["“{name}” is not a usable key name. Use letters, digits and underscores."] = "“{name}” ist kein brauchbarer Schlüsselname. Verwende Buchstaben, Ziffern und Unterstriche.",
    ["“{name}” has its own setting in this form. Use that instead."] = "“{name}” hat in diesem Formular eine eigene Einstellung. Verwende stattdessen diese.",
    ["Use the Longest reply box for the length of a reply, not “{name}”."] = "Für die Länge einer Antwort das Feld Längste Antwort verwenden, nicht „{name}“.",
    ["“{name}” is set by the mod and cannot be changed here."] = "“{name}” wird vom Mod gesetzt und kann hier nicht geändert werden.",
    ["“{name}” needs a number, a text, true or false, or a list of those."] = "“{name}” braucht eine Zahl, einen Text, wahr oder falsch oder eine Liste davon.",
    ["Longest character description, in characters"] = "Längste Charakterbeschreibung, in Zeichen",
    ["Earlier turns kept"] = "Behaltene frühere Runden",
    ["Right-now sentence"] = "Satz zum Augenblick",
    ["Notes for this turn"] = "Notizen für diese Runde",
    ["That prompting option was not found."] = "Diese Prompt-Option wurde nicht gefunden.",
    ["Keep at least one rule."] = "Behalte mindestens eine Regel.",
    ["Rule {n} is empty. Write the rule or delete it."] = "Regel {n} ist leer. Schreib die Regel oder lösche sie.",
    ["Rule {n} is too long. Keep each one under {max} characters."] = "Regel {n} ist zu lang. Halte jede unter {max} Zeichen.",
    ["The rules are too long together. Keep them under {max} characters in all."] = "Die Regeln sind zusammen zu lang. Halte sie insgesamt unter {max} Zeichen.",
    ["This text is too long. Keep it under {max} characters."] = "Dieser Text ist zu lang. Halte ihn unter {max} Zeichen.",
    ["This text cannot be empty."] = "Dieser Text darf nicht leer sein.",
    ["Use a number from {min} to {max}."] = "Verwende eine Zahl von {min} bis {max}.",
    ["Too many stop texts. Keep {max} or fewer."] = "Zu viele Stopptexte. Behalte höchstens {max}.",
    ["A stop text is too long. Keep each one under {max} characters."] = "Ein Stopptext ist zu lang. Halte jeden unter {max} Zeichen.",
    ["{field}: {message}"] = "{field}: {message}",
    ["In use now"] = "Gerade aktiv",
    ["How each conversation option is told to answer. Every option has its own prompting. A change counts from the next reply, and nothing needs restarting."] = "Wie jede Gesprächsoption antworten soll. Jede Option hat ihren eigenen Prompt. Eine Änderung gilt ab der nächsten Antwort, ohne dass etwas neu gestartet werden muss.",
    ["The facts the characters get from the game and a short list of safety filters cannot be edited here. Convai’s prompting lives on Convai’s side."] = "Die Fakten, die die Charaktere aus dem Spiel bekommen, und eine kurze Liste von Sicherheitsfiltern können hier nicht bearbeitet werden. Der Prompt von Convai liegt auf Convais Seite.",
    ["Mistral and Local AI"] = "Mistral und Local AI",
    ["Lite and Standard are the two Local AI model sizes. “Mature on” is used while Mature content is on."] = "Lite und Standard sind die beiden Größen des Local-AI-Modells. „Erwachsene an“ wird verwendet, solange Inhalte für Erwachsene an sind.",
    ["Your Custom models and APIs"] = "Deine eigenen Modelle und APIs",
    ["A Custom model appears here once you choose Custom as the conversation provider and set a model."] = "Ein eigenes Modell erscheint hier, sobald du Eigener als Gesprächsanbieter wählst und ein Modell einstellst.",
    ["From {min} to {max}."] = "Von {min} bis {max}.",
    ["Shipped: {value}"] = "Original: {value}",
    ["Rule {n}"] = "Regel {n}",
    ["Rule {n}, for a speaker with a reply length of its own"] = "Regel {n}, für einen Sprecher mit eigener Antwortlänge",
