    ["Korean"] = "Koreanisch",
    ["Chinese"] = "Chinesisch",
    ["Choose one of the listed reply languages."] = "Wähle eine der aufgelisteten Antwortsprachen.",
    ["No speech was heard. Hold the talk key while you speak."] = "Keine Stimme gehört. Halte die Sprachtaste gedrückt, während du sprichst.",
    ["Voice activation"] = "Sprachaktivierung",
    ["Voice activation could not open the microphone. Check your Windows input device."] = "Sprachaktivierung konnte das Mikrofon nicht öffnen. Prüfe dein Windows-Eingabegerät.",
    ["Voice input could not reach Convai. Hold the voice key again, or type."] = "Die Spracheingabe konnte Convai nicht erreichen. Halte die Sprachtaste erneut gedrückt oder tippe.",
    ["Talk without a key. While you face a character or a companion is near, the mod listens and answers when you pause for about a second.\n\nNever during the game’s own scenes or choices, or while a character speaks. Nothing leaves your PC unless speech is heard. Headphones work best, but a Bluetooth headset’s microphone drops it to call quality while this listens."] = "Reden ohne Taste. Wenn du einem Charakter zugewandt bist oder ein Begleiter in der Nähe ist, hört der Mod zu und antwortet nach etwa einer Sekunde Pause.\n\nNie während Szenen, Dialogauswahlen oder wenn ein Charakter spricht. Nichts verlässt deinen PC, solange keine Sprache gehört wird. Am besten mit Kopfhörern; ein Bluetooth-Headset-Mikro schaltet auf Gesprächsqualität, solange zugehört wird.",
    ["Opening microphone…"] = "Mikrofon wird geöffnet…",
    ["Speak now"] = "Sprich jetzt",
    ["Type in the search box to find a model by name or record, for example “rita wheeler”. A part of a word is enough."] = "Gib im Suchfeld den Namen oder Datensatz ein, um ein Modell zu finden, zum Beispiel „rita wheeler“. Ein Teil eines Wortes genügt.",
    ["Content packs"] = "Inhaltspakete",
    ["Add-ons that change how the characters talk."] = "Erweiterungen, die ändern, wie die Charaktere sprechen.",
    ["Turns the content pack {name} on or off. A pack changes how the characters talk. Its prompt changes work with Mistral, Local AI and Custom. On Convai its world rules and its own Convai characters apply. A switch counts from the next reply, new names after a restart."] = "Schaltet das Inhaltspaket {name} ein oder aus. Ein Paket ändert, wie die Charaktere sprechen. Seine Prompt-Änderungen funktionieren mit Mistral, Local AI und Eigener. Bei Convai gelten seine Weltregeln und seine eigenen Convai-Charaktere. Ein Schalter gilt ab der nächsten Antwort, neue Namen nach einem Neustart.",
    ["Content packs add rules after yours. You cannot edit them here: turn a pack off under Settings > Content packs in the game."] = "Inhaltspakete fügen Regeln nach deinen hinzu. Hier kannst du sie nicht bearbeiten: Schalte ein Paket im Spiel unter Einstellungen > Inhaltspakete aus.",
    ["From the content pack {name}"] = "Aus dem Inhaltspaket {name}",
    ["Content packs that change this prompt: {names}. Your own changes stay on top of theirs, and Reset to default goes back to the pack’s wording."] = "Inhaltspakete, die diesen Prompt ändern: {names}. Deine eigenen Änderungen bleiben über ihren, und Auf Standard zurücksetzen geht zum Wortlaut des Pakets zurück.",
    ["Memory in use"] = "Aktive Erinnerung",
    ["Normal memory"] = "Normale Erinnerung",
    ["Forget memories clears only the memory shown here. The other memory stays as it is."] = "Erinnerungen vergessen löscht nur die hier angezeigte Erinnerung. Die andere Erinnerung bleibt unverändert.",
    ["This clears the memory in use: {memory}."] = "Das löscht die aktive Erinnerung: {memory}.",
    ["Backspace"] = "Rücktaste",
    ["Cancelled."] = "Abgebrochen.",
    ["Caps lock"] = "Feststelltaste",
    ["Choose a key or a controller button."] = "Wähle eine Taste oder eine Controller-Taste.",
    ["Choose the keys and controller buttons for talking by voice or text, the group chats and the Companion Manager. They work at once."] = "Wähle die Tasten und Controller-Tasten für Sprechen per Stimme oder Text, die Gruppenchats und die Begleiterverwaltung. Sie wirken sofort.",
    ["Choose the keys and controller buttons for the mod’s actions. Press Set, then the key or button you want. Esc or B cancels. A change works at once, and the keys you set in Cyber Engine Tweaks keep working. Pick keys the game does not already use."] = "Wähle die Tasten und Controller-Tasten für die Aktionen des Mods. Drücke Festlegen und dann die gewünschte Taste oder Schaltfläche. Esc oder B bricht ab. Eine Änderung wirkt sofort, und die Tasten, die du in Cyber Engine Tweaks belegt hast, funktionieren weiter. Nimm Tasten, die das Spiel noch nicht verwendet.",
    ["Controller {button}"] = "Controller: {button}",
    ["D-pad down"] = "D-Pad unten",
    ["D-pad left"] = "D-Pad links",
    ["D-pad right"] = "D-Pad rechts",
    ["D-pad up"] = "D-Pad oben",
    ["Down arrow"] = "Pfeil runter",
    ["End"] = "Ende",
    ["Enter"] = "Enter",
    ["Group text chat"] = "Gruppen-Textchat",
    ["Group voice chat"] = "Gruppen-Sprachchat",
    ["Hold it to talk to the characters around you at once, and let go to send. Facing nobody, you talk to the first member of your party and two others from it."] = "Halte gedrückt, um mit allen Charakteren in deiner Nähe gleichzeitig zu sprechen, und lass zum Senden los. Wenn du niemanden anschaust, sprichst du mit dem ersten Mitglied deiner Gruppe und zwei weiteren aus der Gruppe.",
    ["Hold it to talk to Johnny, the voice in your head, wherever you face, and let go to send. It needs Johnny in your head turned on in Settings."] = "Halte gedrückt, um mit Johnny zu sprechen, der Stimme in deinem Kopf, egal wohin du dich wendest, und lass zum Senden los. Dafür muss Johnny im Kopf in den Einstellungen eingeschaltet sein.",
    ["Hold the key or button while you speak and let go to send, like the Cyber Engine Tweaks talk key. Facing nobody, you talk to the first member of your party."] = "Halte die Taste oder Schaltfläche beim Sprechen gedrückt und lass zum Senden los, wie bei der Sprechtaste in Cyber Engine Tweaks. Wenn du niemanden anschaust, sprichst du mit dem ersten Mitglied deiner Gruppe.",
    ["Home"] = "Pos1",
    ["Insert"] = "Einfg",
    ["Key bindings"] = "Tastenbelegung",
    ["Key bindings need Codeware, and this game does not have it. Open Help for what is missing."] = "Tastenbelegung braucht Codeware, und das hat dieses Spiel nicht. Öffne die Hilfe, was fehlt.",
    ["Key or button"] = "Taste/Knopf",
    ["Left arrow"] = "Pfeil links",
    ["Menu"] = "Menü",
    ["No key was pressed, so nothing changed."] = "Es wurde keine Taste gedrückt, daher hat sich nichts geändert.",
    ["Not available"] = "Nicht verfügbar",
    ["Not set"] = "Nicht belegt",
    ["Num lock"] = "Num Lock",
    ["Page down"] = "Bild ab",
    ["Page up"] = "Bild auf",
    ["Pause"] = "Pause",
    ["Press it, then the key or controller button you want. Esc or B cancels. It works at once."] = "Drücke darauf und dann die gewünschte Taste oder Controller-Taste. Esc oder B bricht ab. Es wirkt sofort.",
    ["Press it to open the Companion Manager while you play."] = "Drücke sie, um die Begleiterverwaltung während des Spielens zu öffnen.",
    ["Press it to type to the character you face. Facing nobody, you type to the first member of your party."] = "Drücke sie, um dem Charakter zu schreiben, dem du gegenüberstehst. Wenn du niemanden anschaust, schreibst du dem ersten Mitglied deiner Gruppe.",
    ["Press it to type to Johnny, the voice in your head, wherever you face. It needs Johnny in your head turned on in Settings."] = "Drücke sie, um Johnny zu schreiben, der Stimme in deinem Kopf, egal wohin du dich wendest. Dafür muss Johnny im Kopf in den Einstellungen eingeschaltet sein.",
    ["Press it to type to the characters around you at once. Facing nobody, you type to the first member of your party and two others from it."] = "Drücke sie, um allen Charakteren in deiner Nähe gleichzeitig zu schreiben. Wenn du niemanden anschaust, schreibst du dem ersten Mitglied deiner Gruppe und zwei weiteren aus der Gruppe.",
    ["Press the key or controller button for {action}. Esc or B cancels."] = "Drücke die Taste oder Controller-Taste für {action}. Esc oder B bricht ab.",
    ["Print screen"] = "Druck",
    ["Remove the key or button you set here."] = "Entferne die Taste oder Schaltfläche, die du hier belegt hast.",
    ["Right arrow"] = "Pfeil rechts",
    ["Scroll lock"] = "Rollen",
    ["Space"] = "Leertaste",
    ["Tab"] = "Tab",
    ["Talk by text"] = "Per Text sprechen",
    ["Talk by voice"] = "Per Stimme sprechen",
    ["Talk to Johnny by text"] = "Mit Johnny per Text sprechen",
    ["Talk to Johnny by voice"] = "Mit Johnny per Stimme sprechen",
    ["That key is already used for another action."] = "Diese Taste ist schon für eine andere Aktion belegt.",
    ["The mod’s key bindings could not be loaded. Open Help for what is wrong."] = "Die Tastenbelegung des Mods konnte nicht geladen werden. Öffne die Hilfe, was falsch ist.",
    ["The mod’s scripts did not load, so no key can be set. Open Help for what is wrong."] = "Die Skripte des Mods wurden nicht geladen, daher kann keine Taste belegt werden. Öffne die Hilfe, was falsch ist.",
    ["Up arrow"] = "Pfeil hoch",
    ["View"] = "Ansicht",
    ["{action} cleared."] = "{action} geleert.",
    ["{action} is set to {key}."] = "{action} ist auf {key} gesetzt.",
    ["{key} is already used for {other}. Choose another."] = "{key} ist schon für {other} belegt. Wähle eine andere.",
    ["10 minutes"] = "10 Minuten",
    ["2 minutes"] = "2 Minuten",
    ["5 minutes"] = "5 Minuten",
    ["Cancel this meeting. She is not told."] = "Treffen absagen. Sie wird nicht informiert.",
    ["Car"] = "Auto",
    ["Choose how long she waits."] = "Wähle, wie lange sie wartet.",
    ["Choose how she arrives."] = "Wähle, wie sie ankommt.",
    ["Choose one of the listed options."] = "Wähle eine der angezeigten Optionen.",
    ["Choose when she arrives."] = "Wähle, wann sie ankommt.",
    ["Companions travel to you when you invite them: they walk or drive in, text you, wait, and remember if you never come.\n\nOff by default."] = "Begleiter kommen, wenn du sie einlädst: Sie gehen zu Fuß oder fahren vor, schreiben dir, warten und merken sich, wenn du nie kommst.\n\nStandardmäßig aus.",
    ["Fine. Call me when you know what you want."] = "Gut. Melde dich, wenn du weißt, was du willst.",
    ["How long she waits"] = "Wie lange sie wartet",
    ["How long she waits for you after arriving right now. After a timed arrival she waits as long as the delay you chose. The wait stops while you are in a fight, a scene or a menu."] = "Wie lange sie nach dem Ankommen auf dich wartet. Nach einer Ankunft zu bestimmter Zeit wartet sie so lange wie die gewählte Verzögerung. Das Warten stoppt im Kampf, in Szenen und Menüs.",
    ["How she arrives"] = "Wie sie ankommt",
    ["I waited {minutes} minutes at {place} and you never showed. Forget it."] = "Ich habe {minutes} Minuten bei {place} gewartet, und du bist nie aufgetaucht. Vergiss es.",
    ["I'm here at {place}. Where are you?"] = "Ich bin bei {place}. Wo bist du?",
    ["Immersive invitations"] = "Immersive Einladungen",
    ["In 10 minutes"] = "In 10 Minuten",
    ["In 2 minutes"] = "In 2 Minuten",
    ["In 5 minutes"] = "In 5 Minuten",
    ["Invite a companion and she really travels to you: she appears out of sight, walks or drives in, texts you when she is there and waits for you."] = "Lade einen Begleiter ein, und sie kommt wirklich zu dir: Sie taucht außer Sicht auf, geht oder fährt vor, schreibt dir, sobald sie da ist, und wartet auf dich.",
    ["Meet at my waypoint when I ask"] = "Auf Wunsch zu meinem Wegpunkt",
    ["Off: Invite brings a companion to your side at once.\n\nOn: a companion you invite, by the Invite button, the Contacts tab or a text, travels to you and arrives after the time you choose here. She texts you when she is there, waits, and leaves angry (and remembers it) if you never come."] = "Aus: Einladen bringt einen Begleiter sofort an deine Seite.\n\nAn: Ein Begleiter, den du über den Einladen-Knopf, den Tab Kontakte oder eine Nachricht einlädst, kommt zu dir und trifft nach der hier gewählten Zeit ein. Sie schreibt dir, wenn sie da ist, wartet und geht verärgert (und merkt es sich), wenn du nie kommst.",
    ["Right now"] = "Sofort",
    ["Right now: she is on her way as soon as she is ready.\n\nIn 2, 5 or 10 minutes: real minutes of play, so she arrives at that time. She then waits as long as that delay."] = "Sofort: Sie ist unterwegs, sobald sie bereit ist.\n\nIn 2, 5 oder 10 Minuten: echte Spielminuten, sie kommt also zu dieser Zeit an. Danach wartet sie so lange wie diese Verzögerung.",
    ["She texts you"] = "Sie schreibt dir",
    ["She texts you when she arrives, when you cancel and when she gives up. Off: no texts (she still remembers being stood up)."] = "Sie schreibt bei Ankunft, bei deiner Absage und wenn sie aufgibt. Aus: keine Nachrichten, sie merkt sich das Versetzen trotzdem.",
    ["Something came up and I can't make it. Sorry."] = "Es ist was dazwischengekommen, ich schaffe es nicht. Sorry.",
    ["Walk"] = "Zu Fuß",
    ["Walk: she appears out of your sight and walks to you.\n\nCar: when a road is near she drives in, stops on the road, gets out and walks the rest. Without a road she walks. The car stays near for a ride, and is removed when she leaves your group or you both go far from it."] = "Zu Fuß: Sie taucht außer Sicht auf und geht zu dir.\n\nAuto: Ist eine Straße nah, fährt sie vor, hält auf der Straße, steigt aus und geht den Rest zu Fuß. Ohne Straße geht sie. Das Auto bleibt für die Fahrt in der Nähe und verschwindet, wenn sie deine Gruppe verlässt oder ihr beide weit davon weg seid.",
    ["When she arrives"] = "Wenn sie ankommt",
    ["When you ask her to come to your waypoint and a map pin is set, she goes there and says so. Off: she always comes to where you are."] = "Bittest du sie, zu deinem Wegpunkt zu kommen, und ist ein Kartenmarker gesetzt, geht sie dorthin und sagt es. Aus: Sie kommt immer zu dir.",
    ["Your position cannot be read yet."] = "Deine Position kann noch nicht gelesen werden.",
    ["on her way"] = "unterwegs",
    ["the meeting spot"] = "der Treffpunkt",
    ["waiting at {place}"] = "wartet bei {place}",
    ["{name} is already on the way."] = "{name} ist schon unterwegs.",
    ["{name} is on her way."] = "{name} ist unterwegs.",
    ["{name} is on her way. About {minutes} minutes."] = "{name} ist unterwegs. Etwa {minutes} Minuten.",
    ["{name} · {state}"] = "{name} · {state}",
    ["{name}: Good to see you. Let us go."] = "{name}: Schön, dich zu sehen. Los geht’s.",
    ["Corpo Plaza"] = "Corpo Plaza",
    ["Heywood Glen"] = "Heywood Glen",
    ["Megabuilding H10"] = "Megabuilding H10",
    ["Move out"] = "Ausziehen lassen",
    ["That companion is not available."] = "Dieser Begleiter ist nicht verfügbar.",
    ["Watson Northside"] = "Watson Northside",
    ["Westbrook Japantown"] = "Westbrook Japantown",
    ["You do not have that apartment."] = "Du hast diese Wohnung nicht.",
    ["at home"] = "zu Hause",
    ["out"] = "außer Haus",
    ["with you"] = "mit dir",
    ["{count} more housemates"] = "{count} weitere Mitbewohner",
    ["{name} has moved out."] = "{name} ist ausgezogen.",
    ["{name} is back at home."] = "{name} ist wieder zu Hause.",
    ["{name} joins you."] = "{name} schließt sich dir an.",
    ["{name} moves into {apartment}."] = "{name} zieht in {apartment} ein.",
    ["{name} now lives in {apartment} and stays in your party until sent home."] = "{name} wohnt jetzt in {apartment} und bleibt in deiner Gruppe, bis du die Person nach Hause schickst.",
    ["{name} stops living at your place. She stays as she is otherwise."] = "{name} wohnt nicht mehr bei dir. Sonst bleibt alles beim Alten.",
    ["{name} · lives in {apartment} · {state}"] = "{name} · wohnt in {apartment} · {state}",
    ["Companions change outfits"] = "Begleiter wechseln Kleidung",
    ["Your party’s companions change outfits now and then: another look by day and by night, and casual clothes at home, where the character has them.\n\nOnly out of your sight, never in front of you, and only for your party’s own copies, never the game’s own characters. Turning this off keeps what they wear now."] = "Die Begleiter deiner Gruppe wechseln ab und zu ihr Outfit: ein anderer Look bei Tag und bei Nacht sowie Freizeitkleidung zu Hause, wo der Charakter sie hat.\n\nNur außerhalb deines Sichtfelds, nie vor deinen Augen, und nur bei den eigenen Kopien deiner Gruppe, nie bei den Charakteren des Spiels. Wenn du das ausschaltest, behalten sie das, was sie gerade tragen.",
    ["Choose how often companions speak up."] = "Wähle, wie oft sich Begleiter zu Wort melden.",
    ["Companions speak up"] = "Begleiter melden sich",
    ["How V is doing according to other mods, when they are installed: Dark Future’s tiredness, hunger, thirst, nerve and addictions, for example. Also what V visibly wears while an Equipment-EX outfit is on, so characters describe the outfit and not the clothes it hides.\n\nOff by default. Off: it is not sent, and nothing is read from those mods."] = "Wie es V laut anderen Mods geht, wenn sie installiert sind: zum Beispiel Müdigkeit, Hunger, Durst, Nerven und Süchte aus Dark Future. Außerdem, was V sichtbar trägt, solange ein Equipment-EX-Outfit aktiv ist, damit Figuren das Outfit beschreiben und nicht die Kleidung, die es verdeckt.\n\nStandardmäßig aus. Aus: Es wird nichts gesendet, und aus diesen Mods wird nichts gelesen.",
    ["How long it has been since V last talked to this character, in the game and in real days: since last night, or days ago. Said only when the gap is long enough to matter, and not again in the same conversation.\n\nOff: it is not sent, and the mod stops reading the game clock for it."] = "Wie lange es her ist, seit V zuletzt mit dieser Figur gesprochen hat, im Spiel und in echten Tagen: seit letzter Nacht oder vor Tagen. Wird nur gesagt, wenn die Lücke lang genug ist, um zu zählen, und nicht noch einmal im selben Gespräch.\n\nAus: Es wird nichts gesendet, und der Mod liest dafür die Spielzeit nicht mehr.",
    ["Music and TV"] = "Musik und TV",
    ["Other mods’ state"] = "Status anderer Mods",
    ["Speaks up normally"] = "Meldet sich normal",
    ["The song playing on the car radio while V rides with the character, or on V’s pocket radio, and what is on a TV near V.\n\nOff: it is not sent, and the mod stops reading it from the game."] = "Das Lied im Autoradio, wenn V mit der Figur fährt, oder im Taschenradio von V, und was auf einem Fernseher in Vs Nähe läuft.\n\nAus: Es wird nichts gesendet, und der Mod liest es nicht mehr aus dem Spiel.",
    ["Time since last talk"] = "Zeit seit dem letzten Gespräch",
    ["Companions in your party sometimes start talking on their own, at a calm moment or after a scene. With two or more near you, it is often a short chat between up to three of them, and you can join in by talking. Never during fights, scenes, calls or menus.\n\nRarely: about 2 an hour. Normally: about 4. Often (the default): about 6.\n\nWith Johnny speaking up too, the rates add up and they take turns."] = "Begleiter im Team melden sich manchmal von selbst: in ruhigen Momenten oder nach einer Szene. Sind zwei oder mehr in der Nähe, ist es oft ein kurzes Gespräch zu dritt, bei dem man mitreden kann. Nie während Kämpfen, Szenen, Anrufen oder Menüs.\n\nSelten: etwa 2 pro Spielstunde. Normal: etwa 4. Oft (Standard): etwa 6.\n\nWenn auch Johnny sich meldet, addieren sich beide Raten und die Sprecher wechseln sich ab.",
    ["Johnny Silverhand answers the Talk to Johnny keys, as the voice in V’s head, once the story has him there. Give Talk to Johnny a key on the Key bindings page: none is set by default.\n\nOn: he answers when you talk to him. Rarely: he also speaks up on his own, about 2 an hour. Normally: about 4. Often: about 6.\n\nWith companions speaking up too, the rates add up and they take turns."] = "Johnny Silverhand antwortet auf die Gesprächstasten als Stimme in Vs Kopf, sobald die Story ihn dorthin bringt. Belege „Mit Johnny sprechen“ auf der Seite Tastenbelegung; standardmäßig ist keine belegt.\n\nAn: Er antwortet, wenn man ihn anspricht. Selten: etwa 2 pro Stunde von allein. Normal: etwa 4. Oft: etwa 6.\n\nSprechen auch Begleiter, addieren sich die Raten und sie wechseln sich ab.",
    ["Choose which live game info the characters are told, such as location, time, weather, company, health, money, gear, quests, music and TV, and other mods’ state.\n\nAll on by default except other mods’ state, which is off. An off kind is not sent to any conversation provider."] = "Wähle, welche Live-Infos aus dem Spiel den Figuren mitgeteilt werden, zum Beispiel Ort, Uhrzeit, Wetter, Begleiter, Gesundheit, Geld, Ausrüstung, Quests, Musik und TV sowie der Status anderer Mods.\n\nStandardmäßig ist alles an, außer dem Status anderer Mods, der aus ist. Ausgeschaltete Infos werden an keinen Gesprächsanbieter gesendet.",
    ["Housemates"] = "Mitbewohner",
    ["Housemates talk to each other"] = "Mitbewohner unterhalten sich",
    ["When two or more housemates are home with you, they talk to each other now and then."] = "Wenn zwei oder mehr Mitbewohner mit dir zu Hause sind, unterhalten sie sich ab und zu miteinander.",
    ["Characters you tell they can stay at your place move into your apartments and live there."] = "Figuren, denen du sagst, dass sie bei dir wohnen können, ziehen in deine Wohnungen ein und leben dort.",
    ["Characters you tell they can stay at your place move into your apartments and live there.\n\nOff by default."] = "Figuren, denen du sagst, dass sie bei dir wohnen können, ziehen in deine Wohnungen ein und leben dort.\n\nStandardmäßig aus.",
    ["On: characters you tell they can stay at your place move into your apartments and live there, and you can call them along.\n\nOff: nothing of this runs. Turning it off removes them from your apartments but remembers who lived there, so turning it on brings them back."] = "An: Figuren, denen du sagst, dass sie bei dir wohnen können, ziehen in deine Wohnungen ein und leben dort. Du kannst sie mitnehmen.\n\nAus: Nichts davon läuft. Beim Ausschalten ziehen sie aus deinen Wohnungen aus, aber es wird gemerkt, wer dort gewohnt hat, sodass sie beim Einschalten zurückkommen.",
    ["OmniVoice Python"] = "OmniVoice Python",
    ["OmniVoice’s code could not load in it"] = "OmniVoice-Code konnte nicht geladen werden",
    ["PyTorch is not installed in it"] = "PyTorch ist nicht installiert",
    ["Your own Python (omni-python.txt) is being tested. Open this page again in a minute."] = "Dein eigenes Python (omni-python.txt) wird gerade getestet. Öffne diese Seite in einer Minute erneut.",
    ["Your own Python (omni-python.txt) is tested when OmniVoice starts or when this page checks again."] = "Dein eigenes Python (omni-python.txt) wird getestet, wenn OmniVoice startet oder wenn diese Seite erneut prüft.",
    ["Your own Python (omni-python.txt) runs OmniVoice with {backend} on {card}. Experimental."] = "Dein eigenes Python (omni-python.txt) führt OmniVoice mit {backend} auf {card} aus. Experimentell.",
    ["Your own Python (omni-python.txt) was not used: {reason}. OmniVoice uses the Runtime’s Python, which needs an NVIDIA card."] = "Dein eigenes Python (omni-python.txt) wurde nicht verwendet: {reason}. OmniVoice nutzt das Python der Runtime, das eine NVIDIA-Karte benötigt.",
    ["a test on the graphics card failed"] = "ein Test auf der Grafikkarte fehlgeschlagen",
    ["it did not start or did not answer in time"] = "es startete nicht oder antwortete nicht rechtzeitig",
    ["its PyTorch finds no graphics card (no CUDA or ROCm)"] = "das PyTorch findet keine Grafikkarte (kein CUDA oder ROCm)",
    ["the OmniVoice pack is not installed"] = "das OmniVoice-Paket ist nicht installiert",
    ["the file does not name a python.exe that exists"] = "die Datei enthält keine existierende python.exe",
    ["the module {module} is missing in it"] = "das Modul {module} fehlt darin",
    ["1 minute"] = "1 Minute",
    ["2 people"] = "2 Personen",
    ["3 people"] = "3 Personen",
    ["4 people"] = "4 Personen",
    ["Every character who lives at your place moves out at once, from every apartment. Party members who do not live there are not touched. A housemate who is with you stays in your party."] = "Jede Figur, die bei dir wohnt, zieht auf einmal aus, aus jeder Wohnung. Gruppenmitglieder, die nicht dort wohnen, sind nicht betroffen. Ein Mitbewohner, der bei dir ist, bleibt in deiner Gruppe.",
    ["Evict"] = "Ausziehen lassen",
    ["Evict all housemates"] = "Alle Mitbewohner ausziehen lassen",
    ["Housemates in one chat"] = "Mitbewohner in einem Chat",
    ["Housemates moved out: {count}"] = "Mitbewohner sind ausgezogen: {count}",
    ["How long the housemates stay quiet after a chat before they may start another. The Companions speak up setting still limits how many chats come in an hour."] = "Wie lange die Mitbewohner nach einem Chat ruhig bleiben, bevor sie einen anderen beginnen können. Die Einstellung \"Begleiter melden sich\" begrenzt immer noch, wie viele Chats in einer Stunde ankommen.",
    ["How many housemates join one chat when that many are home near each other. They speak one at a time. With fewer at home, the chat is as big as it can be."] = "Wie viele Mitbewohner nehmen an einem Chat teil, wenn so viele zu Hause beieinander sind. Sie sprechen nacheinander. Mit weniger zu Hause ist der Chat so groß wie möglich.",
    ["Move-in apartment"] = "Einzugswohnung",
    ["Nobody lives at your place."] = "Niemand wohnt bei dir.",
    ["Pause between chats"] = "Pause zwischen Chats",
    ["Where a character moves in when you say she can stay but name no apartment and you are not standing in one of yours.\n\nAsk me: she asks which one. Otherwise she takes the apartment you pick here. Only the apartments you own are listed."] = "Wo eine Figur einzieht, wenn du sagst, sie kann bleiben, aber du keine Wohnung benennst und nicht in einer deiner eigenen stehst.\n\nFrag mich: Sie fragt, welche. Sonst nimmt sie die Wohnung, die du hier auswählst. Nur die Wohnungen, die du besitzt, werden angezeigt.",
    ["Ask me"] = "Frag mich",
    ["Could not start"] = "Konnte nicht starten",
    ["Did not start"] = "Nicht gestartet",
    ["If the folder is there, the newest log in red4ext/logs says why RED4ext did not load it: an antivirus that removed a file, or a missing Visual C++ runtime."] = "Wenn der Ordner da ist, zeigt das neueste Protokoll in red4ext/logs, warum RED4ext ihn nicht geladen hat: Ein Virenscanner hat eine Datei entfernt oder die Visual C++ runtime fehlt.",
    ["Load a save first. A key can be set only while a game is loaded."] = "Lade zuerst einen Spielstand. Eine Taste kann nur gesetzt werden, während ein Spiel geladen ist.",
    ["No key press reached the mod, so nothing changed. If keys do not arrive from this menu, set the key in Cyber Engine Tweaks’ Bindings: it works the same."] = "Der Mod hat keinen Tastendruck erhalten, daher hat sich nichts geändert. Kommen Tasten aus diesem Menü nicht an, lege die Taste in den Tastenbelegungen von Cyber Engine Tweaks fest: Das funktioniert genauso.",
    ["Runtime incomplete"] = "Runtime unvollständig",
    ["Runtime not loaded"] = "Runtime nicht geladen",
    ["Service not running ({reason})"] = "Dienst läuft nicht ({reason})",
    ["The Runtime’s plugin is loaded, but the conversation service left no trace in this session. launcher.log in red4ext/plugins/AiNpcCyberpunkCode says why: launcher.ini switched off, Node missing, or Node blocked by a security program. Fix that, then restart the game."] = "Das Plugin der Runtime ist geladen, aber der Gesprächsdienst hat in dieser Sitzung keine Spur hinterlassen. launcher.log in red4ext/plugins/AiNpcCyberpunkCode sagt warum: launcher.ini ausgeschaltet, Node fehlt oder Node wird von einem Sicherheitsprogramm blockiert. Behebe das und starte dann das Spiel neu.",
    ["The conversation service cannot see this mod’s folder in the game: a mod manager’s virtual folders, or a folder it may not read. Extract the Runtime straight into the Cyberpunk 2077 folder, or start the game from the mod manager that holds the Runtime."] = "Der Gesprächsdienst kann den Ordner dieses Mods im Spiel nicht sehen: virtuelle Ordner eines Mod-Managers oder ein Ordner, den er nicht lesen darf. Entpacke die Runtime direkt in den Cyberpunk-2077-Ordner oder starte das Spiel über den Mod-Manager, der die Runtime enthält.",
    ["The conversation service was started and never reported back. A security program probably stopped it at once, or Node cannot run on this PC. Allow red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe in your security program, then restart the game."] = "Der Gesprächsdienst wurde gestartet, hat sich aber nie zurückgemeldet. Wahrscheinlich hat ihn ein Sicherheitsprogramm sofort gestoppt, oder Node kann auf diesem PC nicht laufen. Erlaube red4ext/plugins/AiNpcCyberpunkMod/app/node/node.exe in deinem Sicherheitsprogramm und starte das Spiel danach neu.",
    ["Windows would not let the game start the conversation service (error {error}). A security program may be blocking node.exe in red4ext/plugins/AiNpcCyberpunkMod/app/node: allow it, then restart the game."] = "Windows hat dem Spiel nicht erlaubt, den Gesprächsdienst zu starten (Fehler {error}). Ein Sicherheitsprogramm blockiert vielleicht node.exe in red4ext/plugins/AiNpcCyberpunkMod/app/node: Erlaube es und starte das Spiel dann neu.",
    ["Add a server address first."] = "Zuerst eine Serveradresse hinzufügen.",
    ["Asks the server three times who it is and shows whether it is reachable, how long it takes to answer and its version. It sends no speech."] = "Fragt den Server dreimal, wer er ist, und zeigt, ob er erreichbar ist, wie lange er zum Antworten braucht und welche Version er hat. Es wird keine Sprache gesendet.",
    ["Connected. The server speaks with {voice}."] = "Verbunden. Der Server spricht mit {voice}.",
    ["Custom voices"] = "Eigene Stimmen",
    ["Deletes the saved server address. Remote OmniVoice needs one to speak."] = "Löscht die gespeicherte Serveradresse. Remote-OmniVoice braucht sie zum Sprechen.",
    ["It answers in {ms} ms."] = "Antwortet in {ms} ms.",
    ["Its voice runs on {device}."] = "Seine Stimme läuft auf {device}.",
    ["Loading"] = "Wird geladen",
    ["Not connected. Replies show as text until the server answers."] = "Nicht verbunden. Antworten werden als Text angezeigt, bis der Server antwortet.",
    ["Nothing answered at that address. Check that the server is running, that the address and port are right and that both PCs are on the same network. A server started with its default only listens on its own PC: start it with the listen address 0.0.0.0."] = "Unter dieser Adresse hat nichts geantwortet. Prüfen Sie, ob der Server läuft, ob Adresse und Port stimmen und ob beide PCs im selben Netzwerk sind. Ein Server, der mit seiner Standardeinstellung gestartet wurde, lauscht nur auf seinem eigenen PC: Starten Sie ihn mit der Lauschadresse 0.0.0.0.",
    ["Off. OmniVoice runs on this PC."] = "Aus. OmniVoice läuft auf diesem PC.",
    ["On, but no server address is saved. OmniVoice cannot speak yet."] = "An, aber keine Serveradresse gespeichert. OmniVoice kann noch nicht sprechen.",
    ["On, but no server address is saved. Pocket is used until you add one."] = "An, aber keine Serveradresse gespeichert. Bis du eine hinzufügst, wird Pocket verwendet.",
    ["On, but no server address is saved. The server is not used yet."] = "An, aber keine Serveradresse gespeichert. Der Server wird noch nicht genutzt.",
    ["On, but a cloud voice is chosen under Companion voices, so the server is not used."] = "An, aber unter Begleiterstimmen ist eine Cloud-Stimme gewählt, daher wird der Server nicht genutzt.",
    ["On. Waiting for the conversation service."] = "An. Warten auf den Gesprächsdienst.",
    ["Paste address"] = "Adresse einfügen",
    ["Remote OmniVoice"] = "Remote-OmniVoice",
    ["Render the voices on another PC or graphics card that runs the OmniVoice server, so this PC keeps its frames.\n\nTurn it on, press Apply and add the server address below. The server then speaks for every Pocket or OmniVoice choice under Companion voices; a cloud voice stays as chosen. If it cannot be reached, replies show as text and the mod retries every few seconds."] = "Stimmen auf einem anderen PC oder einer anderen Grafikkarte mit OmniVoice-Server berechnen, damit dieser PC seine Bildrate behält.\n\nEinschalten, Übernehmen drücken, Serveradresse unten eintragen. Der Server spricht dann jede Pocket- oder OmniVoice-Wahl unter Begleiterstimmen; Cloud-Stimmen bleiben. Ohne Verbindung erscheinen Antworten als Text, und der Mod versucht es alle paar Sekunden erneut.",
    ["Render the OmniVoice voices on another PC or graphics card that runs the OmniVoice server."] = "OmniVoice-Stimmen auf einem anderen PC oder einer anderen Grafikkarte berechnen lassen, auf dem bzw. der der OmniVoice-Server läuft.",
    ["Render Pocket and OmniVoice voices on another PC or graphics card: the on/off switch, the server address and a connection test. It works whichever of those voices is chosen above."] = "Pocket- und OmniVoice-Stimmen auf einem anderen PC oder einer anderen Grafikkarte berechnen lassen: Ein/Aus-Schalter, Serveradresse und Verbindungstest. Es funktioniert, egal welche dieser Stimmen oben gewählt ist.",
    ["Server address"] = "Serveradresse",
    ["Something answered, but it is not the OmniVoice server. Check the port."] = "Es hat etwas geantwortet, aber es ist nicht der OmniVoice-Server. Prüfen Sie den Port.",
    ["Start the OmniVoice server on the other PC. Its window shows the address to use, for example 192.168.1.20:8765. Copy it, then choose Paste address. It is read from the clipboard once and saved on this computer.\n\nOn the same PC use 127.0.0.1:8765. You can also write address=192.168.1.20:8765 in player-remote-omnivoice.txt in the conversation service folder.\n\nNothing is sent to it until Remote OmniVoice is on and OmniVoice is chosen, or you press Test."] = "Starten Sie den OmniVoice-Server auf dem anderen PC. Sein Fenster zeigt die zu verwendende Adresse, zum Beispiel 192.168.1.20:8765. Kopieren Sie sie und wählen Sie dann Adresse einfügen. Sie wird einmal aus der Zwischenablage gelesen und auf diesem Computer gespeichert.\n\nAuf demselben PC verwenden Sie 127.0.0.1:8765. Sie können auch address=192.168.1.20:8765 in die Datei player-remote-omnivoice.txt im Ordner des Gesprächsdienstes schreiben.\n\nAn ihn wird nichts gesendet, bis Remote-OmniVoice eingeschaltet und OmniVoice gewählt ist oder Sie Verbindung testen drücken.",
    ["Status"] = "Status",
    ["The OmniVoice server cannot be reached. Replies show as text until it answers. The mod asks it again every few seconds."] = "Der OmniVoice-Server ist nicht erreichbar. Antworten werden als Text angezeigt, bis er antwortet. Der Mod fragt ihn alle paar Sekunden erneut.",
    ["The clipboard does not hold a server address."] = "Die Zwischenablage enthält keine Serveradresse.",
    ["The clipboard is empty. Copy the address first."] = "Die Zwischenablage ist leer. Kopieren Sie zuerst die Adresse.",
    ["The port must be a number from 1 to 65535."] = "Der Port muss eine Zahl von 1 bis 65535 sein.",
    ["The server address was removed."] = "Die Serveradresse wurde entfernt.",
    ["The server answered but could not load its voice. Its window says why."] = "Der Server hat geantwortet, konnte seine Stimme aber nicht laden. Sein Fenster nennt den Grund.",
    ["The server answered but is still loading its voice. Try again in a minute."] = "Der Server hat geantwortet, lädt seine Stimme aber noch. Versuchen Sie es in einer Minute erneut.",
    ["The server is another version. Use the server folder and the mod from the same release."] = "Der Server hat eine andere Version. Verwenden Sie den Serverordner und den Mod aus derselben Veröffentlichung.",
    ["The server is ready."] = "Der Server ist bereit.",
    ["The server refused the request."] = "Der Server hat die Anfrage abgelehnt.",
    ["The server took too long to answer."] = "Der Server hat zu lange für die Antwort gebraucht.",
    ["Use the address only: no user name, no path, no #."] = "Nur die Adresse eingeben: kein Benutzername, kein Pfad, kein #.",
    ["Use the address the server window shows, such as 192.168.1.20:8765, without https://."] = "Die Adresse eingeben, die das Serverfenster zeigt, zum Beispiel 192.168.1.20:8765, ohne https://.",
    ["Waiting for the server to answer…"] = "Warten auf die Antwort des Servers…",
    ["Whether the server is in use right now. It is checked when a voice is needed and again every few seconds after a failure, never while you play."] = "Ob der Server gerade in Benutzung ist. Er wird geprüft, wenn eine Stimme benötigt wird, und nach einem Fehler alle paar Sekunden erneut, nie während des Spielens.",
    ["Your own character, made in the character editor."] = "Dein eigener Charakter, im Charaktereditor erstellt.",
    ["They join as a copy of the model they were made from. They talk with Mistral, Local AI or Custom; with Convai they talk as an ordinary person."] = "Er schließt sich als Kopie des Modells an, aus dem er gemacht wurde. Er spricht mit Mistral, Local AI oder Eigener; mit Convai spricht er wie eine ganz normale Person.",
    ["This character needs Mistral, Local AI or Custom to answer."] = "Dieser Charakter braucht Mistral, Local AI oder Eigener, um zu antworten.",
    ["Build for your game"] = "Build für dein Spiel",
    ["Your game is {game} but the Runtime is the one for game {runtime}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over this one, then restart the game."] = "Dein Spiel ist {game}, aber die Runtime ist die für Spiel {runtime}. Lade das vollständige Installations-ZIP für Spiel {game} von der Nexus-Mods-Seite des Mods (Hauptdatei für Spiel 2.5, optionale Datei für Spiel 2.31) herunter, entpacke es im Ordner Cyberpunk 2077 über die vorhandenen Dateien und starte dann das Spiel neu.",
    ["Your game is {game} but the Scripts are the build for game {scripts}. Get the update zip for game {game} from the mod’s Nexus Mods page (the update file is for game 2.5, the optional update file for game 2.31) and install it over these, then restart the game."] = "Dein Spiel ist {game}, aber die Scripts sind der Build für Spiel {scripts}. Lade das Update-ZIP für Spiel {game} von der Nexus-Mods-Seite des Mods (das Update ist für Spiel 2.5, das optionale Update für Spiel 2.31) herunter und installiere es über die vorhandenen Dateien, dann starte das Spiel neu.",
    ["Your game is {game} but the Scripts and the Runtime are the build for game {scripts}. Get the full install zip for game {game} from the mod’s Nexus Mods page (main file for game 2.5, optional file for game 2.31) and extract it into the Cyberpunk 2077 folder over these, then restart the game."] = "Dein Spiel ist {game}, aber die Scripts und die Runtime sind der Build für Spiel {scripts}. Lade das vollständige Installations-ZIP für Spiel {game} von der Nexus-Mods-Seite des Mods (Hauptdatei für Spiel 2.5, optionale Datei für Spiel 2.31) herunter, entpacke es im Ordner Cyberpunk 2077 über die vorhandenen Dateien und starte dann das Spiel neu.",
    ["The Scripts are the build for game {scripts} but the Runtime is the build for game {runtime}, and the game version matches neither. Extract the full install zip made for the same game as yours (from Nexus Mods) into the Cyberpunk 2077 folder, then restart the game."] = "Die Scripts sind der Build für Spiel {scripts}, die Runtime dagegen der Build für Spiel {runtime}, und die Spielversion passt zu keinem von beiden. Entpacke das vollständige Installations-ZIP für dasselbe Spiel wie deins (von Nexus Mods) in den Ordner Cyberpunk 2077 und starte danach das Spiel neu.",
    ["The Runtime is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Die Runtime ist für Spiel {other}, deins ist {game}. Hol das Komplett-ZIP für {game}.",
    ["The Scripts are for game {other}, yours is {game}. Get the update zip for {game}."] = "Die Scripts sind für Spiel {other}, deins ist {game}. Hol das Update-ZIP für {game}.",
    ["This mod is for game {other}, yours is {game}. Get the full install zip for {game}."] = "Der Mod ist für Spiel {other}, deins ist {game}. Hol das Komplett-ZIP für {game}.",
    ["Scripts are for game {scripts}, Runtime for {runtime}. They must match. See Help in Settings."] = "Scripts für Spiel {scripts}, Runtime für {runtime}. Müssen passen. Hilfe in Einstellungen.",
    ["Choose one of the listed microphones."] = "Wähle eines der aufgelisteten Mikrofone.",
    ["Microphone"] = "Mikrofon",
    ["The microphone you chose in Settings ({chosen}) is not connected, so the Windows default input is used: {name}."] = "Das in den Einstellungen gewählte Mikrofon ({chosen}) ist nicht verbunden, daher wird die Windows-Standardeingabe verwendet: {name}.",
    ["The microphone you chose in Settings is not connected, so the Windows default input is used."] = "Das in den Einstellungen gewählte Mikrofon ist nicht verbunden, daher wird die Windows-Standardeingabe verwendet.",
    ["Windows default"] = "Windows-Standard",
    ["not connected"] = "nicht verbunden",
    ["{name}, chosen in Settings > Voices."] = "{name}, in Einstellungen > Stimmen gewählt.",
    ["{name}, the Windows default input. Settings > Voices > Microphone chooses another."] = "{name}, die Windows-Standardeingabe. Eine andere wählst du unter Einstellungen > Stimmen > Mikrofon.",
    ["Gameplay"] = "Spielablauf",
    ["Revenge ambushes"] = "Rachehinterhalte",
    ["A gang you keep killing may rarely send a small squad after you, with a short threat to shout. A long wait follows each one.\n\nNever in a fight, scene, call, vehicle, indoors, safe zone or while wanted. The threats need Talk to ordinary NPCs."] = "Eine Gang, die du immer wieder tötest, schickt dir selten einen kleinen Trupp mit einer kurzen Drohung. Danach folgt eine lange Wartezeit.\n\nNie im Kampf, in Szenen, bei Anrufen, im Fahrzeug, in Innenräumen, in sicheren Zonen oder solange du gesucht wirst. Die Drohungen brauchen „Mit gewöhnlichen NPCs sprechen“.",
    ["Speak dialogue choices"] = "Dialogoptionen sprechen",
    ["Say a dialogue choice to pick it: its words, a part of them, or its number (\"two\", \"the last one\"). If nothing fits clearly, nothing is picked. No character answers.\n\nPresses the arrow keys and Enter, so the game must be in front. Needs speech recognition on this PC. Headphones work best."] = "Sag eine Dialogoption, um sie zu wählen: ihre Worte, einen Teil davon oder ihre Nummer (\"zwei\", \"die letzte\"). Passt nichts eindeutig, wird nichts gewählt. Keine Figur antwortet.\n\nEs drückt die Pfeiltasten und Enter, daher muss das Spiel im Vordergrund sein. Braucht Spracherkennung auf diesem PC. Kopfhörer funktionieren am besten.",
    ["No option matched. Say its number."] = "Keine Option passte. Sag ihre Nummer.",
    ["Two options fit. Say its number."] = "Zwei Optionen passen. Sag ihre Nummer.",
    ["Speaking a choice needs speech recognition on this PC."] = "Eine Option zu sprechen braucht Spracherkennung auf diesem PC.",
    ["AMD’s ROCm PyTorch does not support this card yet."] = "AMDs ROCm PyTorch unterstützt diese Karte noch nicht.",
    ["Another setup is already running. Wait for it to finish."] = "Eine andere Einrichtung läuft bereits. Warte, bis sie fertig ist.",
    ["Cancelled"] = "Abgebrochen",
    ["Cancelling…"] = "Wird abgebrochen…",
    ["Checking your card…"] = "Grafikkarte wird geprüft…",
    ["Downloading {done} of {total} MB ({percent}%)"] = "Lade {done} von {total} MB herunter ({percent}%)",
    ["Downloading…"] = "Wird heruntergeladen…",
    ["Experimental. Pocket speaks until it is ready. A local voice never switches to a cloud voice."] = "Experimentell. Pocket spricht, bis OmniVoice fertig ist. Eine lokale Stimme wechselt nie zu einer Cloud-Stimme.",
    ["Frees about {disk} GB."] = "Gibt etwa {disk} GB frei.",
    ["Frees the space it took."] = "Gibt den belegten Platz wieder frei.",
    ["Install"] = "Installieren",
    ["Installed"] = "Installiert",
    ["Installed. OmniVoice uses it when it starts."] = "Installiert. OmniVoice nutzt es, wenn es startet.",
    ["It is kept in the mod’s data folder on drive C:."] = "Es liegt im Datenordner des Mods auf Laufwerk C:.",
    ["It runs in the background while you play. The game keeps running and nothing else changes."] = "Es läuft im Hintergrund, während du spielst. Das Spiel läuft weiter, und sonst ändert sich nichts.",
    ["It takes about {disk} GB on drive C: in the mod’s data folder."] = "Es braucht etwa {disk} GB auf Laufwerk C: im Datenordner des Mods.",
    ["MIOpen convolutions (AMD)"] = "MIOpen-Faltungen (AMD)",
    ["Not available on this PC. It needs an AMD Radeon card and the OmniVoice pack."] = "Auf diesem PC nicht verfügbar. Es braucht eine AMD Radeon-Karte und das OmniVoice-Paket.",
    ["OmniVoice for AMD"] = "OmniVoice für AMD",
    ["OmniVoice on AMD: set up first"] = "OmniVoice auf AMD: zuerst einrichten",
    ["OmniVoice then no longer starts on this card until it is set up again."] = "OmniVoice startet auf dieser Karte dann nicht mehr, bis es erneut eingerichtet wird.",
    ["On: AMD’s MIOpen runs the convolutions, with MIOPEN_FIND_MODE=2 and MIOPEN_FIND_ENFORCE=1. Off: PyTorch’s own convolutions. Which is faster depends on your card and driver: if voices are slow or stop part-way, try the other one. AMD cards only. OmniVoice restarts with the new choice when it is idle."] = "An: AMDs MIOpen führt die Faltungen aus, mit MIOPEN_FIND_MODE=2 und MIOPEN_FIND_ENFORCE=1. Aus: die eigenen Faltungen von PyTorch. Welche schneller ist, hängt von deiner Karte und dem Treiber ab: Wenn Stimmen langsam sind oder mittendrin aussetzen, probier die andere. Nur für AMD-Karten. OmniVoice startet mit der neuen Wahl neu, wenn es gerade untätig ist.",
    ["Own Python"] = "Eigenes Python",
    ["Ready"] = "Bereit",
    ["Ready. OmniVoice runs on {card} with AMD’s ROCm."] = "Bereit. OmniVoice läuft mit {card} über AMDs ROCm.",
    ["Reinstall"] = "Neu installieren",
    ["Remove AMD setup"] = "AMD-Einrichtung entfernen",
    ["Removing the AMD setup…"] = "Die AMD-Einrichtung wird entfernt…",
    ["Run OmniVoice on your AMD Radeon card with AMD’s ROCm: one download, set up from here."] = "Betreibe OmniVoice auf deiner AMD Radeon-Karte mit AMDs ROCm: ein Download, hier eingerichtet.",
    ["Set up OmniVoice for AMD"] = "OmniVoice für AMD einrichten",
    ["Starting the AMD setup…"] = "Die AMD-Einrichtung wird gestartet…",
    ["Testing it on your card…"] = "Wird auf deiner Karte getestet…",
    ["The AMD setup was removed."] = "Die AMD-Einrichtung wurde entfernt.",
    ["The OmniVoice pack is not installed. Install it first."] = "Das OmniVoice-Paket ist nicht installiert. Installiere es zuerst.",
    ["The conversation service is not running. Restart the game."] = "Der Gesprächsdienst läuft nicht. Starte das Spiel neu.",
    ["The download did not finish. Check your connection and try again."] = "Der Download ist nicht fertig geworden. Prüfe deine Verbindung und versuche es noch einmal.",
    ["The download is not ready yet in this version of the mod."] = "Der Download ist in dieser Version des Mods noch nicht verfügbar.",
    ["The downloaded files did not check out. Try again."] = "Die heruntergeladenen Dateien sind nicht in Ordnung. Versuche es noch einmal.",
    ["The files could not be unpacked. Try again."] = "Die Dateien konnten nicht entpackt werden. Versuche es noch einmal.",
    ["The setup did not finish. Try again."] = "Die Einrichtung ist nicht fertig geworden. Versuche es noch einmal.",
    ["The setup did not pass the test on your card, so OmniVoice cannot use it."] = "Die Einrichtung hat den Test auf deiner Karte nicht bestanden, deshalb kann OmniVoice sie nicht nutzen.",
    ["The setup is installed but did not pass the test on your card. Choose Reinstall."] = "Die Einrichtung ist installiert, hat den Test auf deiner Karte aber nicht bestanden. Wähle Neu installieren.",
    ["There is not enough free space on drive C:. Free some up and try again."] = "Auf Laufwerk C: ist nicht genug freier Speicher. Gib etwas frei und versuche es noch einmal.",
    ["This PC has no AMD Radeon card this setup can use."] = "Dieser PC hat keine AMD Radeon-Karte, die diese Einrichtung nutzen kann.",
    ["Unpacking…"] = "Wird entpackt…",
    ["Your own Python (omni-python.txt) is used instead. Delete that file to use this setup."] = "Dein eigenes Python (omni-python.txt) wird stattdessen genutzt. Lösche diese Datei, um diese Einrichtung zu nutzen.",
    ["your AMD card"] = "deine AMD-Karte",
    ["{voice} · AMD: set up first"] = "{voice} · AMD: zuerst einrichten",
    ["The AMD setup (Settings > Voices > OmniVoice for AMD) runs OmniVoice with ROCm on {card}. Experimental."] = "Die AMD-Einrichtung (Einstellungen > Stimmen > OmniVoice für AMD) führt OmniVoice mit ROCm auf {card} aus. Experimentell.",
    ["The AMD setup was not used: {reason}. Choose Reinstall in Settings > Voices > OmniVoice for AMD. Until then Pocket speaks."] = "Die AMD-Einrichtung wurde nicht genutzt: {reason}. Wähle Neu installieren unter Einstellungen > Stimmen > OmniVoice für AMD. Bis dahin spricht Pocket.",
    ["Borrow eddies from your characters, lend them eddies and pay each other back, by talking. Each character has money of their own, as their story has it, and decides by how they feel about you. Now and then they ask you for a loan.\n\nEddies change hands as soon as a character agrees, and only with your own characters (party, invited visitors, housemates). The game’s own characters only talk about it. Off by default."] = "Leih dir Eddies von deinen Figuren, leih ihnen welche und zahlt euch im Gespräch zurück. Jede Figur hat eigenes Geld und entscheidet nach ihrer Meinung über dich. Ab und zu bitten sie dich um einen Kredit.\n\nEddies wechseln den Besitzer, sobald eine Figur zustimmt, und nur mit deinen eigenen Figuren (Gruppe, Gäste, Mitbewohner). Die Spielfiguren reden nur darüber. Standardmäßig aus.",
    ["Eddies with characters"] = "Eddies mit Figuren",
    ["Character bonds"] = "Bindungen zu Figuren",
    ["Every named character has a bond with you, level 1 to 10. Quests finished together, a romance, eddies paid back and talking raise it; threats and insults lower it. Closer characters trust you more.\n\nA notice shows each level change. Forget clears the talk part. Off by default."] = "Jede benannte Figur hat eine Bindung zu dir, Stufe 1 bis 10. Gemeinsam abgeschlossene Aufträge, eine Romanze, zurückgezahlte Eddies und Gespräche stärken sie; Drohungen und Beleidigungen schwächen sie. Nähere Figuren vertrauen dir mehr.\n\nEin Hinweis zeigt jede Stufenänderung. Vergessen löscht den Gesprächsteil. Standardmäßig aus.",
    ["Bond with {name}: level {level}, {title}"] = "Bindung zu {name}: Stufe {level}, {title}",
    ["Bond with {name} fell: level {level}, {title}"] = "Bindung zu {name} gesunken: Stufe {level}, {title}",
    ["Acquaintance"] = "Bekanntschaft",
    ["Familiar face"] = "Bekanntes Gesicht",
    ["Friendly"] = "Freundlich",
    ["Friend"] = "Freund",
    ["Good friend"] = "Guter Freund",
    ["Close friend"] = "Enger Freund",
    ["Trusted"] = "Vertraut",
    ["Confidant"] = "Vertrauter",
    ["Family"] = "Familie",
    ["Ride or die"] = "Bis in den Tod",
    ["Story packs"] = "Geschichtenpakete",
    ["When you are close and a character’s own quests are done, they can start a short story of their own. It plays out in talks, texts and calls, and some use Eddies with characters and Immersive invitations.\n\nNeeds Character bonds. Own characters and channels only, never the game’s own scenes or quests. Off by default."] = "Wenn du einer Figur nahestehst und ihre eigenen Aufträge erledigt sind, kann sie eine kurze eigene Geschichte beginnen. Sie läuft in Gesprächen, Nachrichten und Anrufen, manche nutzen Eddies mit Figuren und Immersive Einladungen.\n\nBraucht Bindungen zu Figuren. Nur eigene Figuren und Kanäle, nie Szenen oder Aufträge des Spiels. Standardmäßig aus.",
    ["Characters text first"] = "Figuren melden sich zuerst",
    ["Characters you are close to can text or call you first now and then, and Johnny can speak up in your head. It only happens at calm moments, never in a fight, a scene or a call, and only a few times a day.\n\nNeeds Story packs. Own characters and channels only. On by default."] = "Figuren, denen du nahestehst, können dir ab und zu zuerst schreiben oder dich anrufen, und Johnny kann sich in deinem Kopf melden. Das passiert nur in ruhigen Momenten, nie in einem Kampf, einer Szene oder einem Anruf, und nur wenige Male am Tag.\n\nBraucht Geschichtenpakete. Nur eigene Figuren und Kanäle. Standardmäßig an.",
    ["Bond: level {level}, {title}"] = "Bindung: Stufe {level}, {title}",
    ["Story: {title}"] = "Geschichte: {title}",
    ["The eddies could not be moved."] = "Die Eddies konnten nicht verschoben werden.",
    ["You do not have enough eddies for that."] = "Dafür hast du nicht genug Eddies.",
    ["{name} is no longer with you, so no eddies moved."] = "{name} ist nicht mehr bei dir, deshalb wurden keine Eddies verschoben.",
    ["Add to favorites"] = "Zu Favoriten hinzufügen",
    ["One download of about {size} GB."] = "Ein Download mit etwa {size} GB.",
    ["One download."] = "Ein Download.",
    ["Remove from favorites"] = "Aus Favoriten entfernen",
    ["Set up OmniVoice on your AMD Radeon card with one download, and choose how it runs."] = "Richte OmniVoice auf deiner AMD Radeon-Karte mit einem Download ein und wähle, wie es läuft.",
    ["That entry cannot be a favorite."] = "Dieser Eintrag kann kein Favorit sein.",
    ["You have too many favorites. Remove one first."] = "Du hast zu viele Favoriten. Entferne zuerst einen.",
    ["Your AMD Radeon card ({card}) can run OmniVoice. Set it up in Settings > Voices > OmniVoice for AMD: one download, then it starts by itself."] = "Deine AMD Radeon-Karte ({card}) kann OmniVoice ausführen. Richte es unter Einstellungen > Stimmen > OmniVoice für AMD ein: ein Download, danach startet es von selbst.",
    ["Your AMD Radeon card can run OmniVoice. Set it up in Settings > Voices > OmniVoice for AMD: one download, then it starts by itself. Until then Pocket speaks."] = "Deine AMD Radeon-Karte kann OmniVoice ausführen. Richte es unter Einstellungen > Stimmen > OmniVoice für AMD ein: ein Download, danach startet es von selbst. Bis dahin spricht Pocket.",
    ["Your favorites could not be saved, so they last only until the game closes."] = "Deine Favoriten konnten nicht gespeichert werden, sie bleiben daher nur bis zum Schließen des Spiels erhalten.",
    ["{count} matching characters"] = "{count} passende Charaktere",
    ["{name} is no longer a favorite."] = "{name} ist kein Favorit mehr.",
    ["A saved party holds {count} characters, so the rest were left out."] = "Eine gespeicherte Gruppe fasst {count} Charaktere, der Rest wurde deshalb weggelassen.",
    ["Already with you: {names}."] = "Schon bei dir: {names}.",
    ["Another saved party already has that name."] = "Eine andere gespeicherte Gruppe hat diesen Namen bereits.",
    ["Could not invite: {names}."] = "Konnte nicht einladen: {names}.",
    ["Deletes this saved party. The characters in your party now are not touched."] = "Löscht diese gespeicherte Gruppe. Die Charaktere in deiner aktuellen Gruppe bleiben unberührt.",
    ["Invites the characters of this party to your side: {names}.\n\nIt adds to your party and dismisses nobody. A character who is already with you is not invited twice. Anyone who cannot come is named, with the reason."] = "Lädt die Charaktere dieser Gruppe zu dir ein: {names}.\n\nEs werden Charaktere zu deiner Gruppe hinzugefügt, niemand wird entlassen. Ein Charakter, der schon bei dir ist, wird nicht doppelt eingeladen. Wer nicht kommen kann, wird samt Grund genannt.",
    ["Parties"] = "Gruppen",
    ["Party"] = "Gruppe",
    ["Press Delete again to delete {name}."] = "Drücke noch einmal Löschen, um {name} zu löschen.",
    ["Press again"] = "Nochmal drücken",
    ["Press again to delete this saved party. Anything else cancels."] = "Drücke noch einmal, um diese gespeicherte Gruppe zu löschen. Alles andere bricht ab.",
    ["Rename"] = "Umbenennen",
    ["Rename party"] = "Gruppe umbenennen",
    ["Renamed to {name}."] = "Umbenannt in {name}.",
    ["Replaces the characters of this saved party with the ones in your party now."] = "Ersetzt die Charaktere dieser gespeicherten Gruppe durch die Charaktere, die jetzt in deiner Gruppe sind.",
    ["Save current party"] = "Aktuelle Gruppe speichern",
    ["Saved as {name}. Press Spawn party under it to invite them again."] = "Gespeichert als {name}. Drücke darunter Gruppe einladen, um sie erneut einzuladen.",
    ["Saved party: {name}"] = "Gespeicherte Gruppe: {name}",
    ["Saves the characters in your party now, copies and your own characters included, as a party you can invite again with one press. It is named Party 1, Party 2 and so on, and appears below.\n\nYou keep up to {count} saved parties."] = "Speichert die Charaktere, die jetzt in deiner Gruppe sind, einschließlich Kopien und eigener Charaktere, als Gruppe, die du mit einem Tastendruck erneut einladen kannst. Sie heißt Gruppe 1, Gruppe 2 und so weiter und erscheint unten.\n\nDu kannst bis zu {count} gespeicherte Gruppen behalten.",
    ["Spawn"] = "Einladen",
    ["Spawn party"] = "Gruppe einladen",
    ["That party no longer exists."] = "Diese Gruppe existiert nicht mehr.",
    ["The characters of this party: {names}."] = "Die Charaktere dieser Gruppe: {names}.",
    ["The party could not be saved."] = "Die Gruppe konnte nicht gespeichert werden.",
    ["This menu has no text box, so the party keeps its name. Mod Configuration Menu has one: type the name in its Search box."] = "Dieses Menü hat kein Textfeld, deshalb behält die Gruppe ihren Namen. Mod Configuration Menu hat eines: Tippe den Namen in dessen Suchfeld.",
    ["Type the new name in the Search box at the top (Mod Configuration Menu), then press Rename. Native Settings UI has no text box, so a party keeps its name there."] = "Tippe den neuen Namen oben in das Suchfeld (Mod Configuration Menu) und drücke dann Umbenennen. Native Settings UI hat kein Textfeld, dort behält eine Gruppe ihren Namen.",
    ["Type the new name in the Search box first, then press Rename."] = "Tippe zuerst den neuen Namen in das Suchfeld und drücke dann Umbenennen.",
    ["Update"] = "Aktualisieren",
    ["Update with current party"] = "Mit aktueller Gruppe aktualisieren",
    ["You can keep {count} saved parties. Delete one first."] = "Du kannst {count} gespeicherte Gruppen behalten. Lösche zuerst eine.",
    ["Your party is empty. Invite someone first."] = "Deine Gruppe ist leer. Lade zuerst jemanden ein.",
    ["Your saved parties could not be written to disk, so they last only until the game closes."] = "Deine gespeicherten Gruppen konnten nicht auf die Festplatte geschrieben werden, daher bleiben sie nur bis zum Schließen des Spiels erhalten.",
    ["that character model is unavailable"] = "Charaktermodell nicht verfügbar",
    ["the invitation was refused"] = "Einladung abgelehnt",
    ["{name} ({count})"] = "{name} ({count})",
    ["{name} ({reason})"] = "{name} ({reason})",
    ["{name} deleted."] = "{name} gelöscht.",
    ["{name} has nobody to invite."] = "{name} hat niemanden zum Einladen.",
    ["{name} now has the characters of your party."] = "{name} hat jetzt die Charaktere deiner Gruppe.",
    ["{party}: inviting {names}."] = "{party}: lädt {names} ein.",
    ["Adds {name} to your favorites. They are listed at the top of page 1, and first in the phone’s Chat tab. Updates never touch them."] = "Fügt {name} den Favoriten hinzu. Sie stehen oben auf Seite 1 und ganz vorn im Chat-Tab des Handys. Updates verändern sie nie.",
    ["Favorites"] = "Favoriten",
    ["Only the first {count} favorites are listed here. The others are in the list below."] = "Hier stehen nur die ersten {count} Favoriten. Die übrigen stehen in der Liste darunter.",
    ["Page {page} of {pages}: {kind} {first} to {last}."] = "Seite {page} von {pages}: {kind} {first} bis {last}.",
    ["Press to go to page {page} of {pages}: {kind} {first} to {last}."] = "Drücken, um zu Seite {page} von {pages} zu wechseln: {kind} {first} bis {last}.",
    ["Takes {name} out of your favorites. Her place in the list below stays."] = "Entfernt {name} aus den Favoriten. Der Platz in der Liste darunter bleibt erhalten.",
    ["This is the first page."] = "Dies ist die erste Seite.",
    ["This is the last page."] = "Dies ist die letzte Seite.",
    ["characters"] = "Charaktere",
    ["entries"] = "Einträge",
    ["models"] = "Modelle",
    ["{count} more favorites"] = "{count} weitere Favoriten",
    ["{name} is now a favorite. Favorites are at the top of page 1."] = "{name} ist jetzt ein Favorit. Favoriten stehen oben auf Seite 1.",
    ["Favorite"] = "Favorit",
    ["That look is not one of this character’s."] = "Dieses Aussehen gehört nicht zu diesem Charakter.",
    ["That choice is not available."] = "Diese Auswahl ist nicht verfügbar.",
    ["The editor keeps choices for {max} characters. Reset one first."] = "Der Editor speichert Auswahlen für {max} Charaktere. Setzen Sie zuerst eine davon zurück.",
    ["Usual look"] = "Gewohnter Look",
    ["Home clothes: tank top, boxer shorts, flip-flops"] = "Hauskleidung: Tanktop, Boxershorts, Flip-Flops",
    ["No jacket"] = "Keine Jacke",
    ["No jacket and harness"] = "Keine Jacke, mit Geschirr",
    ["Home clothes: shirt and trousers"] = "Hauskleidung: Hemd und Hose",
    ["Home clothes: tank top and trousers"] = "Hauskleidung: Tanktop und Hose",
    ["Hooded jacket"] = "Kapuzenjacke",
    ["Home clothes: t-shirt and trousers"] = "Hauskleidung: T-Shirt und Hose",
    ["Collar down"] = "Kragen offen",
    ["Valentino look"] = "Valentino-Look",
    ["Suit"] = "Anzug",
    ["Club night, no jacket"] = "Clubnacht, ohne Jacke",
    ["Solo look"] = "Solo-Look",
    ["Date night"] = "Date-Abend",
    ["T-shirt"] = "T-Shirt",
    ["Vest"] = "Weste",
    ["Paradise look"] = "Paradise-Look",
    ["Bartender"] = "Barkeeper",
    ["Dress without the fur coat"] = "Kleid ohne Pelzmantel",
    ["Trench coat"] = "Trenchcoat",
    ["Without the coat"] = "Ohne Mantel",
    ["CEO look with coat"] = "CEO-Look mit Mantel",
    ["CEO look"] = "CEO-Look",
    ["Pyjamas"] = "Schlafanzug",
    ["Go back to the usual look and moves for {name}? Your choices on this part are removed."] = "Zum gewohnten Look und zu den Bewegungen für {name} zurückkehren? Ihre Auswahl in diesem Bereich wird entfernt.",
    ["Back to the usual look and moves."] = "Zurück zum gewohnten Look und zu den Bewegungen.",
    ["Choices for how this character looks and moves. They work with every conversation option, Convai included, except the reply length."] = "Auswahl, wie diese Figur aussieht und sich bewegt. Sie wirkt mit jeder Gesprächsoption zusammen, auch mit Convai, außer mit der Antwortlänge.",
    ["Outfit"] = "Kleidung",
    ["Automatic follows the “Companions change outfits” setting in the game: day and night looks, now and then a change, and casual clothes at home. A look you pick is worn all the time. Only your own companions and residents are dressed, and they change while nobody is looking. Characters the game places are never changed."] = "Automatisch folgt der Einstellung im Spiel „Begleiter wechseln Kleidung“: Tages- und Nachtlooks, ab und zu ein Wechsel und Freizeitkleidung zu Hause. Ein gewählter Look wird immer getragen. Nur Ihre eigenen Begleiter und Bewohner werden eingekleidet, und sie wechseln, wenn niemand hinsieht. Vom Spiel platzierte Charaktere werden nie verändert.",
    ["This character has only one look in the game files, so there is no outfit to choose."] = "Diese Figur hat in den Spieldateien nur einen Look, daher gibt es keine Kleidung zur Auswahl.",
    ["Talking gestures"] = "Gesten beim Sprechen",
    ["How the hands move while they speak a longer reply."] = "Wie sich die Hände bewegen, während sie eine längere Antwort sprechen.",
    ["Normal"] = "Normal",
    ["Calm: smaller gestures, not as often"] = "Ruhig: kleinere Gesten, nicht so oft",
    ["Lively: bigger gestures, more often"] = "Lebhaft: größere Gesten, öfter",
    ["None: the hands stay at rest"] = "Keine: die Hände bleiben ruhig",
    ["Nod while you talk to them"] = "Beim Sprechen mit ihnen nicken",
    ["A small nod now and then while you speak."] = "Ab und zu ein kleines Nicken, während Sie sprechen.",
    ["Idle moves"] = "Leerlaufbewegungen",
    ["What they do now and then while they stand beside you."] = "Was sie ab und zu tun, während sie neben Ihnen stehen.",
    ["Plain stances only, no props like a cup or a cigarette"] = "Nur einfache Haltungen, keine Requisiten wie Becher oder Zigarette",
    ["None: they keep the stance they have"] = "Keine: sie behalten ihre Haltung bei",
    ["Sit down and take a place"] = "Hinsetzen und einen Platz nehmen",
    ["Takes a seat beside you when you sit, and a seat or a spot in your flat at home. Switched off, they stay on their feet beside you."] = "Setzt sich neben Sie, wenn Sie sich hinsetzen, und nimmt in Ihrer Wohnung einen Sitzplatz oder eine Stelle ein. Ausgeschaltet bleiben sie neben Ihnen auf den Beinen.",
    ["Comment on fights and loot"] = "Kommentare zu Kämpfen und Beute",
    ["Switched off, they say nothing about fights or about what you pick up."] = "Ausgeschaltet sagen sie nichts zu Kämpfen oder zu dem, was Sie aufheben.",
    ["Reply length"] = "Antwortlänge",
    ["The longest reply, in words. Works with Mistral, Local AI and Custom, not Convai."] = "Die längste Antwort in Wörtern. Funktioniert mit Mistral, Local AI und Custom, nicht mit Convai.",
    ["Shorter: up to about {words} words"] = "Kürzer: bis etwa {words} Wörter",
    ["Very short: up to about {words} words"] = "Sehr kurz: bis etwa {words} Wörter",
    ["A saved choice counts within a few seconds. Clothes change when nobody is looking."] = "Eine gespeicherte Auswahl wird innerhalb weniger Sekunden übernommen. Kleidung wechselt, wenn niemand hinsieht.",
    ["Look and moves"] = "Look und Bewegungen",
    ["Shift"] = "Umschalt",
    ["Ctrl"] = "Strg",
    ["Alt"] = "Alt",
    ["Hold Shift, Ctrl or Alt while you press a key to set a combination such as Shift+F5. A combination runs only with exactly those keys held, and a plain key does not run while one is held. In the game Shift sprints, Ctrl dodges and Alt opens the weapon wheel, so V does that too."] = "Halte Umschalt, Strg oder Alt gedrückt, während du eine Taste drückst, um eine Kombination wie Umschalt+F5 festzulegen. Eine Kombination läuft nur, wenn genau diese Tasten gehalten werden, und eine einfache Taste läuft nicht, solange eine davon gehalten wird. Im Spiel sprintet Umschalt, Strg weicht aus und Alt öffnet das Waffenrad, also tut V das ebenfalls.",
    ["Bonds are not kept while Character bonds is off, so nobody is listed here. Turn it on in Settings, under Gameplay."] = "Bindungen werden nicht festgehalten, solange Bindungen zu Figuren aus ist, deshalb ist hier niemand aufgeführt. Schalte sie unter Einstellungen im Bereich Spielablauf ein.",
    ["Character bonds are off"] = "Bindungen zu Figuren sind aus",
    ["From their story: {story}, from talking: {talk}"] = "Aus ihrer Geschichte: {story}, aus Gesprächen: {talk}",
    ["Highest level"] = "Höchste Stufe",
    ["Hurt: {points}"] = "Gekränkt: {points}",
    ["Hurt: {points}, gone in about a game day"] = "Gekränkt: {points}, in etwa einem Spieltag vorbei",
    ["Hurt: {points}, gone in about {days} game days"] = "Gekränkt: {points}, in etwa {days} Spieltagen vorbei",
    ["Last talked: today"] = "Zuletzt gesprochen: heute",
    ["Last talked: yesterday"] = "Zuletzt gesprochen: gestern",
    ["Last talked: {days} days ago"] = "Zuletzt gesprochen: vor {days} Tagen",
    ["Level {level}"] = "Stufe {level}",
    ["No story yet"] = "Noch keine Geschichte",
    ["Nobody yet"] = "Noch niemand",
    ["See the characters you have talked to and how close each one is to you: the bond level, what raised or hurt it, their quests and the stories they are in."] = "Sieh dir die Figuren an, mit denen du gesprochen hast, und wie nah dir jede steht: die Bindungsstufe, was sie gehoben oder verletzt hat, ihre Aufträge und die Geschichten, in denen sie stecken.",
    ["Talk to a character and your bond with them shows here."] = "Sprich mit einer Figur, und deine Bindung zu ihr erscheint hier.",
    ["The characters you have talked to and how close each one is to you. The most recent come first."] = "Die Figuren, mit denen du gesprochen hast, und wie nah dir jede steht. Die neuesten stehen oben.",
    ["Their quests: {done} of {total} finished"] = "Ihre Aufträge: {done} von {total} erledigt",
    ["Warmth: {points}"] = "Wärme: {points}",
    ["{points} of {needed} points to level {to}"] = "{points} von {needed} Punkten bis Stufe {to}",
    ["{title} (finished)"] = "{title} (abgeschlossen)",
    ["{title}: {label}"] = "{title}: {label}",
    ["Mistral’s limit is reached for now. Try again in a moment."] = "Das Limit von Mistral ist vorerst erreicht. Versuche es gleich noch einmal.",
    ["Mistral API key"] = "Mistral-API-Schlüssel",
    ["Mistral: limit reached for now"] = "Mistral: Limit vorerst erreicht",
    ["The Local AI model you chose needs about {need} MB of graphics memory, but only {available} MB are available for it beside the game, so {model} was used instead."] = "Das gewählte Local-AI-Modell braucht etwa {need} MB Grafikspeicher, aber neben dem Spiel stehen dafür nur {available} MB zur Verfügung, daher wurde stattdessen {model} verwendet.",
    ["The conversation limit has been reached. Try again later, or choose Local AI or Mistral in Settings > Conversation provider."] = "Das Gesprächslimit wurde erreicht. Versuche es später erneut, oder wähle unter Einstellungen > Gesprächsanbieter Local AI oder Mistral.",
    ["You’ve reached today’s Convai free tier limit. It resets tomorrow. To keep talking now, choose another provider in Settings > Conversation provider. Local AI is unlimited and runs on your PC. Mistral works with your own key."] = "Du hast das heutige Limit von Convai (kostenloser Tarif) erreicht. Morgen wird es zurückgesetzt. Um jetzt weiterzusprechen, wähle unter Einstellungen > Gesprächsanbieter einen anderen Anbieter. Local AI ist unbegrenzt und läuft auf deinem PC. Mistral funktioniert mit deinem eigenen Schlüssel.",
    ["You’ve reached today’s Convai free tier limit. It resets at {time}. To keep talking now, choose another provider in Settings > Conversation provider. Local AI is unlimited and runs on your PC. Mistral works with your own key."] = "Du hast das heutige Limit von Convai (kostenloser Tarif) erreicht. Reset um {time}. Um jetzt weiterzusprechen, wähle unter Einstellungen > Gesprächsanbieter einen anderen Anbieter. Local AI ist unbegrenzt und läuft auf deinem PC. Mistral funktioniert mit deinem eigenen Schlüssel.",
    ["Today’s {limit} Convai turns are used.\nTry Local AI (unlimited) or Mistral (your own key)."] = "{limit} Convai-Runden heute weg.\nLocal AI (unbegrenzt) oder Mistral (eigener Schlüssel).",
    ["Today’s {limit} Convai turns are used.\nIt resets at {time}. Try Local AI (unlimited) or Mistral (your own key)."] = "{limit} Convai-Runden heute weg.\nReset um {time}. Local AI (unbegrenzt) oder Mistral (eigener Schlüssel).",
    ["Today’s Convai turns are used.\nTry Local AI (unlimited) or Mistral (your own key)."] = "Heutige Convai-Runden weg.\nLocal AI (unbegrenzt) oder Mistral (eigener Schlüssel).",
    ["Today’s Convai turns are used.\nIt resets at {time}. Try Local AI (unlimited) or Mistral (your own key)."] = "Heutige Convai-Runden weg.\nReset um {time}. Local AI (unbegrenzt) oder Mistral (eigener Schlüssel).",
    ["You have used today’s {limit} turns, which come back tomorrow. To keep talking now, choose Local AI (unlimited) or Mistral (with your own key)."] = "Heute sind deine {limit} Runden aufgebraucht und kommen morgen zurück. Zum Weitersprechen wähle Local AI (kein Limit) oder Mistral (mit eigenem Schlüssel).",
    ["You have used today’s {limit} turns, which come back at {time}. To keep talking now, choose Local AI (unlimited) or Mistral (with your own key)."] = "Heute sind deine {limit} Runden aufgebraucht und kommen um {time} zurück. Zum Weitersprechen wähle Local AI (kein Limit) oder Mistral (mit eigenem Schlüssel).",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key. Mistral uses your own Mistral key, and its memory stays on this computer.\n\nWith Mistral, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works."] = "Wer die Antworten deiner Begleiter schreibt. Eine Änderung wartet, bis kein Gespräch läuft.\n\nDer kostenlose Tarif von Convai braucht keine Einrichtung und liefert bessere Antworten. Die Option Convai-API-Schlüssel nutzt deinen eigenen Schlüssel. Mistral nutzt deinen eigenen Mistral-Schlüssel, und die Erinnerungen bleiben auf diesem Computer.\n\nMit Mistral, Local AI oder Eigener wird die Cloud-Stimme von Convai durch eine lokale Stimme ersetzt. Die Spracherkennung läuft auf diesem Computer, damit die Sprachtaste funktioniert.",
    ["Who writes your companions’ replies. A change waits until no conversation is running.\n\nConvai free tier needs no setup and gives better replies. Convai API key uses your own key. Mistral uses your own Mistral key, and its memory stays on this computer.\n\nWith Mistral, Local AI or Custom, Convai’s cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with them, so type your messages."] = "Wer die Antworten deiner Begleiter schreibt. Eine Änderung wartet, bis kein Gespräch läuft.\n\nDer kostenlose Tarif von Convai braucht keine Einrichtung und liefert bessere Antworten. Die Option Convai-API-Schlüssel nutzt deinen eigenen Schlüssel. Mistral nutzt deinen eigenen Mistral-Schlüssel, und die Erinnerungen bleiben auf diesem Computer.\n\nMit Mistral, Local AI oder Eigener wird die Cloud-Stimme von Convai durch eine lokale Stimme ersetzt. Die Spracherkennung für die Sprachtaste ist mit ihnen noch nicht verfügbar, tippe deshalb deine Nachrichten.",
    ["Local AI is back on your graphics card, so replies are faster again."] = "Local AI läuft wieder auf deiner Grafikkarte, deshalb sind die Antworten wieder schneller.",
    ["Voice files"] = "Sprachdateien",
    ["The voice files are incomplete. Reinstall the Full download from Nexus Mods."] = "Die Sprachdateien sind unvollständig. Installiere das Komplett-ZIP von Nexus Mods erneut.",
    ["The voice files are incomplete, so the voices and the microphone cannot start. Reinstall the Full download from Nexus Mods: extract it into the Cyberpunk 2077 folder and let it replace the files, then restart the game."] = "Die Sprachdateien sind unvollständig, deshalb können die Stimmen und das Mikrofon nicht starten. Installiere das vollständige Installations-ZIP von Nexus Mods erneut: Entpacke es in den Ordner Cyberpunk 2077 und lass die Dateien ersetzen, dann starte das Spiel neu.",
    ["Copy your key from Mistral first (new Mistral accounts need a paid plan for an API key). It is read from the clipboard once, checked with Mistral and saved on this computer.\n\nYou can also save it in player-mistral-key.txt in the conversation service folder."] = "Kopiere zuerst deinen Schlüssel von Mistral (neue Mistral-Konten brauchen für einen API-Schlüssel einen kostenpflichtigen Tarif). Er wird einmal aus der Zwischenablage gelesen, geprüft und auf diesem PC gespeichert.\n\nDu kannst ihn auch in player-mistral-key.txt im Ordner des Dienstes speichern.",
    ["When something in the mod goes wrong, a short report goes to the developer so it can be fixed.\n\nIt never holds keys, what you or the characters say, memories, audio or your Windows user name.\n\nIt holds the error, versions, your settings, PC details (graphics card, processor, Windows, security software, game drive, screen), installed mod names, setup check, reply timings and the log lines around it (for setup problems and script errors also the Cyber Engine Tweaks log)."] = "Bei einem Fehler im Mod geht ein kurzer Bericht an den Entwickler.\n\nEr enthält nie Schlüssel, was du oder die Charaktere sagen, Erinnerungen, Audio oder deinen Windows-Benutzernamen.\n\nEr enthält den Fehler, Versionen, deine Einstellungen, PC-Angaben (Grafikkarte, Prozessor, Windows, Sicherheitsprogramme, Spiel-Laufwerk, Bildschirm), Mod-Namen, Installationsprüfung, Antwortzeiten und Protokollzeilen um den Fehler (bei Installationsproblemen und Skriptfehlern auch das Protokoll von Cyber Engine Tweaks).",
    ["The wording added while Mature content is on. The mod picks the explicit or the suggestive version of a line from what the loaded model allows, so edit the version your model uses. An emptied box leaves that line out. The adults-only line and the hard limits are always added last and cannot be edited."] = "Die Formulierungen, die hinzukommen, wenn Inhalte für Erwachsene an sind. Der Mod wählt je nach geladenem Modell die explizite oder die andeutende Version einer Zeile. Bearbeite die Version, die dein Modell nutzt. Ein geleertes Feld lässt diese Zeile weg. Die Zeile nur für Erwachsene und die harten Grenzen werden immer zuletzt angefügt und können nicht bearbeitet werden.",
    ["Disk space"] = "Speicherplatz",
    ["Your {drive} drive is almost full ({free} GB free). Free space so the mod can save logs and memories."] = "Dein Laufwerk {drive} ist fast voll ({free} GB frei). Gib Platz frei für Logs und Erinnerungen des Mods.",
    ["An input marked (!) looks like a loopback or virtual input, such as Stereo Mix, CABLE Output or a mixer’s Out. It can carry other apps’ sound, for example the far side of a call, so the mod never picks one by itself."] = "Eine mit (!) markierte Eingabe sieht nach einem Loopback oder virtuellen Eingang aus, etwa Stereo Mix, CABLE Output oder dem Ausgang eines Mixers. Sie kann den Ton anderer Apps übertragen, zum Beispiel die Gegenseite eines Anrufs, deshalb wählt der Mod nie selbst eine davon aus.",
    ["The input you chose looks like it carries PC sound, not only your voice. If characters hear your calls, choose your real microphone."] = "Die gewählte Eingabe scheint PC-Ton zu übertragen, nicht nur deine Stimme. Wenn Figuren deine Anrufe hören, wähle dein echtes Mikrofon.",
    ["{name} looks like it carries PC sound, such as a call, not only your voice. Choose your real microphone in Settings > Voices > Microphone."] = "{name} scheint PC-Ton zu übertragen, etwa einen Anruf, nicht nur deine Stimme. Wähle dein echtes Mikrofon unter Einstellungen > Stimmen > Mikrofon.",
    ["Companions can see"] = "Begleiter können sehen",
    ["Each line also gets a recent picture of your surroundings, taken from the game window just before you talk. Works with every conversation provider. Local AI needs a model that can see. A model that cannot just gets your words.\n\nOnly the game window, only while someone is near, kept briefly in memory. Off means nothing is captured."] = "Jede Zeile bekommt auch ein aktuelles Bild deiner Umgebung aus dem Spielfenster. Funktioniert mit jedem Gesprächsanbieter. Local AI braucht ein Modell, das sehen kann. Ohne das bekommt es nur deine Worte.\n\nNur das Spielfenster, nur wenn jemand in der Nähe ist, kurz im Speicher. Aus bedeutet, dass nichts aufgenommen wird.",
    ["The yellow border is Windows showing a capture. Turn off Companions can see to stop it."] = "Der gelbe Rahmen zeigt eine Windows-Aufnahme. Zum Stoppen Begleiter können sehen deaktivieren.",
    ["This Local AI model cannot see pictures, so replies use only your words."] = "Dieses Local AI Modell sieht keine Bilder, daher fließen nur deine Worte ein.",
    ["This model can see pictures with its vision file, from {folder}/vision on Hugging Face."] = "Dieses Modell sieht Bilder mit der Vision-Datei von {folder}/vision auf Hugging Face.",
    ["Your Custom endpoint does not accept pictures, so replies use only your words."] = "Dein Custom-Endpunkt nimmt keine Bilder an, daher fließen nur deine Worte ein.",
    ["Google Gemini (free)"] = "Google Gemini (kostenlos)",
    ["Groq (free)"] = "Groq (kostenlos)",
    ["Use"] = "Verwenden",
    ["Fills in the endpoint URL and the model ID for the free plan of Google Gemini (Flash-Lite). Then make a free key at aistudio.google.com/apikey (a Google account is enough, no card) and paste it below.\n\nThe free plan has a daily limit, is not offered in every country, and Google may use free-plan chats to improve its products."] = "Fülle die Endpunkt-URL und die Modell-ID für den kostenlosen Tarif von Google Gemini (Flash-Lite) aus. Erstelle dann unter aistudio.google.com/apikey einen kostenlosen Schlüssel (ein Google-Konto reicht, keine Karte nötig) und füge ihn unten ein.\n\nDer kostenlose Tarif hat ein Tageslimit, ist nicht in jedem Land verfügbar, und Google kann Chats aus dem kostenlosen Tarif nutzen, um seine Produkte zu verbessern.",
    ["Fills in the endpoint URL and the model ID for the free plan of Groq (Qwen). Then make a free key at console.groq.com/keys (no card) and paste it below.\n\nReplies come very fast, but the free plan is small: about one reply a minute and a few dozen a day. It is not offered in every country."] = "Fülle die Endpunkt-URL und die Modell-ID für den kostenlosen Tarif von Groq (Qwen) aus. Erstelle dann unter console.groq.com/keys einen kostenlosen Schlüssel (ohne Karte) und füge ihn unten ein.\n\nDie Antworten kommen sehr schnell, aber der kostenlose Tarif ist klein: etwa eine Antwort pro Minute und ein paar Dutzend am Tag. Er ist nicht in jedem Land verfügbar.",
}
